/* Curriculum follows the supplied жоспар.docx. */
const CURRICULUM = [{"id":"numbers","title":"Сандар және есептеулер","color":"#91afff","symbol":"ℝ","lessons":[{"id":"numbers-01","title":"Натурал, бүтін, рационал сандар","rule":"Натурал сандар — санау сандары; бүтін сандарға нөл мен теріс бүтіндер де кіреді.","trap":"2,5 — бүтін сан.","problems":[{"q":"−3; 0; 2,5; 7 сандарының ішіндегі натурал санды жаз.","answer":"7","steps":["Натурал сан санауда қолданылады.","берілген тізімде ол — 7."]},{"q":"−4 пен 3 арасындағы бүтін сандарды, шеткі сандарын қоспай, сана.","answer":"6","steps":["Сандар: −3, −2, −1, 0, 1, 2.","барлығы 6."]}]},{"id":"numbers-02","title":"Жай және ондық бөлшектер","rule":"Бөлшектерді қосу үшін ортақ бөлімге келтіреміз.","trap":"1/2 + 1/3 = 2/5.","problems":[{"q":"3/4 + 1/8 мәнін ондық бөлшекпен жаз.","answer":"0.875","steps":["3/4 = 6/8.","6/8 + 1/8 = 7/8 = 0,875."]},{"q":"2,4 ÷ 0,6 мәнін тап.","answer":"4","steps":["Екі санды да 10-ға көбейт.","24 ÷ 6 = 4."]}]},{"id":"numbers-03","title":"Оң және теріс сандар","rule":"Таңбалары әртүрлі сандарды қосқанда модульдерінің айырмасын табамыз.","trap":"Екі теріс санның көбейтіндісі теріс болады.","problems":[{"q":"Таңертең −7°C болды, күндіз 12°C-қа жылынды. Температура қанша болды?","answer":"5","steps":["−7 + 12 = 5.","температура +5°C болды."]},{"q":"(−6) × (−4) − 30 мәнін тап.","answer":"-6","steps":["Екі теріс санның көбейтіндісі оң.","24 − 30 = −6."]}]},{"id":"numbers-04","title":"Амалдардың орындалу реті","rule":"Алдымен жақша, одан кейін дәреже, көбейту мен бөлу, соңында қосу мен азайту орындалады.","trap":"Көбейту әрқашан бөлуден бұрын орындалады.","problems":[{"q":"18 − 2 × (3 + 4) мәнін тап.","answer":"4","steps":["Жақша: 3 + 4 = 7.","18 − 14 = 4."]},{"q":"48 ÷ 6 × 2 + 3² мәнін тап.","answer":"25","steps":["Бөлу мен көбейту солдан оңға: 8 × 2 = 16.","16 + 9 = 25."]}]},{"id":"numbers-05","title":"Бөлінгіштік белгілері","rule":"Цифрлар қосындысы 3-ке бөлінсе, санның өзі де 3-ке бөлінеді.","trap":"Соңғы цифры 5 болатын әр сан 2-ге бөлінеді.","problems":[{"q":"4□2 саны 9-ға бөлінуі үшін бос орынға қандай цифр жазылады?","answer":"3","steps":["4 + □ + 2 = 6 + □.","9-ға бөлінетін жалғыз қосынды — 9, сондықтан □ = 3."]},{"q":"1-ден 30-ға дейінгі сандардың нешеуі 5-ке бөлінеді?","answer":"6","steps":["Сандар: 5, 10, 15, 20, 25, 30.","барлығы 6."]}]},{"id":"numbers-06","title":"Жай және құрама сандар","rule":"Жай санның екі оң бөлгіші бар; 1 жай да, құрама да емес.","trap":"1 — жай сан.","problems":[{"q":"10 мен 20 арасындағы жай сандардың санын тап.","answer":"4","steps":["Жай сандар: 11, 13, 17, 19.","барлығы 4."]},{"q":"21 санының ең кіші жай бөлгішін тап.","answer":"3","steps":["21 = 3 × 7.","ең кіші жай бөлгіш — 3."]}]},{"id":"numbers-07","title":"Жұп және тақ сандар","rule":"Жұп сандар 2-ге қалдықсыз бөлінеді; тақ және жұп санның қосындысы тақ болады.","trap":"Екі тақ санның қосындысы тақ болады.","problems":[{"q":"15-тен кейінгі қатар тұрған бес жұп санның қосындысын тап.","answer":"100","steps":["Сандар: 16, 18, 20, 22, 24.","қосындысы 100."]},{"q":"Үш қатар тұрған тақ санның ең кішісі 9. Олардың қосындысы қанша?","answer":"33","steps":["Сандар: 9, 11, 13.","9 + 11 + 13 = 33."]}]},{"id":"numbers-08","title":"Ең үлкен ортақ бөлгіш (ЕҮОБ)","rule":"ЕҮОБ — екі санға да қалдықсыз бөлгіш болатын ең үлкен сан.","trap":"ЕҮОБ екі санның әрқайсысынан үлкен болады.","problems":[{"q":"36 және 48 сандарының ЕҮОБ-ын тап.","answer":"12","steps":["36 = 3 × 12, 48 = 4 × 12.","ең үлкен ортақ бөлгіш — 12."]},{"q":"24 алма мен 18 алмұртты бірдей құрамды неше сыйлыққа ең көбі бөлуге болады?","answer":"6","steps":["Қорап саны екі санды да бөлуі керек.","ЕҮОБ(24,18) = 6."]}]},{"id":"numbers-09","title":"Ең кіші ортақ еселік (ЕКОЕ)","rule":"ЕКОЕ — екі санға да еселік болатын ең кіші оң сан.","trap":"ЕКОЕ әрқашан екі санның қосындысына тең.","problems":[{"q":"12 және 18 сандарының ЕКОЕ-сін тап.","answer":"36","steps":["12 еселіктері: 12, 24, 36.","18 еселіктері: 18, 36.","алғашқы ортақ сан — 36."]},{"q":"Екі шам 8 және 12 секунд сайын жанады. Бірге жанғаннан кейін неше секундтан соң қайта бірге жанады?","answer":"24","steps":["Қайталану уақыты — ЕКОЕ(8,12).","ол 24 секунд."]}]},{"id":"numbers-10","title":"Дәреже және түбір","rule":"Дәреже көбейтудің қайталануын білдіреді; квадрат түбір квадратқа кері амал.","trap":"3² = 3 × 2.","problems":[{"q":"√144 + 2³ мәнін тап.","answer":"20","steps":["√144 = 12.","2³ = 8.","қосындысы 20."]},{"q":"5² − √81 мәнін тап.","answer":"16","steps":["5² = 25.","√81 = 9.","25 − 9 = 16."]}]},{"id":"numbers-11","title":"Санның соңғы цифрын табу","rule":"Соңғы цифрлар дәрежелерде белгілі циклмен қайталанады.","trap":"7-нің кез келген дәрежесі 7 цифрымен аяқталады.","problems":[{"q":"7²⁰ санының соңғы цифрын тап.","answer":"1","steps":["7 дәрежелерінің соңғы цифрлары: 7, 9, 3, 1.","20 саны 4-ке бөлінеді, жауап 1."]},{"q":"2¹¹ санының соңғы цифрын тап.","answer":"8","steps":["Цикл: 2, 4, 8, 6.","11-ді 4-ке бөлгендегі қалдық 3, жауап 8."]}]},{"id":"numbers-12","title":"Сандық заңдылықтар","rule":"Заңдылықты табу үшін айырма, қатынас және кезектесуді тексереміз.","trap":"Заңдылық тек алғашқы екі мүшеге сәйкес келсе жеткілікті.","problems":[{"q":"2, 5, 10, 17, 26, … тізбегінің келесі санын тап.","answer":"37","steps":["Айырмалар: 3, 5, 7, 9.","келесі айырма 11, сондықтан 26 + 11 = 37."]},{"q":"1, 1, 2, 3, 5, 8, … келесі санды тап.","answer":"13","steps":["Әр мүше алдыңғы екеуінің қосындысы.","5 + 8 = 13."]}]},{"id":"numbers-13","title":"Дөңгелектеу және жуық мәндер","rule":"Дөңгелектеуде келесі разрядтағы цифр 5-тен кем болмаса, сақталатын разрядты арттырамыз.","trap":"3,149 санын жүздік үлеске дөңгелектесек, 3,14 шығады.","problems":[{"q":"7,486 санын жүздік үлеске дейін дөңгелекте.","answer":"7.49","steps":["Жүздік үлес — 8.","келесі цифр 6 болғандықтан 7,49 шығады."]},{"q":"48 650 санын мыңдыққа дейін дөңгелекте.","answer":"49000","steps":["Жүздіктер цифры 6.","48 мың 49 мыңға дейін дөңгелектенеді."]}]}],"number":1},{"id":"percent","title":"Пайыз және пропорция","color":"#bb9cff","symbol":"%","lessons":[{"id":"percent-01","title":"Санның пайызын табу","rule":"Санның пайызын табу үшін санды пайызға көбейтіп, 100-ге бөлеміз.","trap":"20% табу үшін санды 20-ға бөлеміз.","problems":[{"q":"240 санының 15%-ын тап.","answer":"36","steps":["15% = 0,15.","240 × 0,15 = 36."]},{"q":"600 орынның 35%-ы толды. Неше орын толды?","answer":"210","steps":["600 × 35 / 100 = 210.","толған орын саны — 210."]}]},{"id":"percent-02","title":"Пайызы бойынша санды табу","rule":"Пайызы белгілі санды табу үшін бөлікті пайыздың ондық үлесіне бөлеміз.","trap":"Санның 25%-ы 20 болса, сол сан 5-ке тең.","problems":[{"q":"Бір санның 30%-ы 72-ге тең. Сол санды тап.","answer":"240","steps":["0,3x = 72.","x = 72 / 0,3 = 240."]},{"q":"Жинақтың 12%-ы 18 000 ₸. Барлық жинақ қанша теңге?","answer":"150000","steps":["0,12x = 18 000.","x = 150 000 ₸."]}]},{"id":"percent-03","title":"Бір санның екінші саннан неше пайыз екенін анықтау","rule":"Бөлік пайызын табу үшін бөлікті бүтінге бөліп, 100%-ға көбейтеміз.","trap":"20 саны 80 санының 40%-ы.","problems":[{"q":"18 саны 60 санының неше пайызы?","answer":"30","steps":["18 / 60 × 100% = 30%."]},{"q":"45 оқушының 9-ы олимпиадаға қатысты. Бұл неше пайыз?","answer":"20","steps":["9 / 45 = 0,2.","0,2 × 100% = 20%."]}]},{"id":"percent-04","title":"Пайызға арттыру және кеміту","rule":"Пайызға арттыру коэффициенті 1 + p/100, кеміту коэффициенті 1 − p/100.","trap":"20%-ға арттыру үшін санды 0,2-ге көбейтеміз.","problems":[{"q":"500 санын 18%-ға арттыр.","answer":"590","steps":["500 × 1,18 = 590.","өсім 90."]},{"q":"800 санын 12,5%-ға кеміт.","answer":"700","steps":["800 × 0,125 = 100.","800 − 100 = 700."]}]},{"id":"percent-05","title":"Бірнеше рет пайызға өзгерту","rule":"Бірнеше пайыздық өзгерістің коэффициенттері көбейтіледі.","trap":"Баға 20%-ға өсіп, 20%-ға кемісе, бастапқы мәнге қайтады.","problems":[{"q":"10 000 ₸ баға 20%-ға өсіп, кейін 20%-ға төмендеді. Соңғы баға қанша?","answer":"9600","steps":["10 000 × 1,2 = 12 000.","12 000 × 0,8 = 9 600 ₸."]},{"q":"5 000 ₸ баға екі рет 10%-ға өсті. Соңғы баға қанша?","answer":"6050","steps":["Бірінші өсімнен кейін 5 500.","екінші өсімнен кейін 5 500 × 1,1 = 6 050."]}]},{"id":"percent-06","title":"Жеңілдік және үстеме баға","rule":"Жеңілдік бағаны азайтады, үстеме баға сатып алу бағасына қосылады.","trap":"25% үстеме мен 25% жеңілдік бірін-бірі әрқашан жояды.","problems":[{"q":"Өзіндік құны 8 000 ₸ затқа 25% үстеме қосылды. Сату бағасы қанша?","answer":"10000","steps":["Үстеме: 8 000 × 0,25 = 2 000.","сату бағасы 10 000 ₸."]},{"q":"24 000 ₸ күртеге 15% жеңілдік берілді. Төлем қанша?","answer":"20400","steps":["Жеңілдік: 3 600 ₸.","24 000 − 3 600 = 20 400 ₸."]}]},{"id":"percent-07","title":"Бастапқы бағаны анықтау","rule":"Бастапқы баға соңғы бағаны өзгеріс коэффициентіне бөлу арқылы табылады.","trap":"Жеңілдікке дейінгі бағаны табу үшін соңғы бағаға сол пайызды қосу жеткілікті.","problems":[{"q":"20% жеңілдіктен кейін баға 12 000 ₸ болды. Бастапқы баға қанша?","answer":"15000","steps":["Бастапқы бағаның 80%-ы 12 000.","12 000 / 0,8 = 15 000."]},{"q":"Баға 10%-ға өскен соң 22 000 ₸ болды. Бұрын қанша еді?","answer":"20000","steps":["1,1x = 22 000.","x = 20 000 ₸."]}]},{"id":"percent-08","title":"Қатынас және пропорция","rule":"Пропорцияда айқыш көбейтінділер тең болады.","trap":"2:3 қатынасында бөлсек, бірінші бөлік бүтіннің жартысы болады.","problems":[{"q":"x : 15 = 4 : 5. x-ті тап.","answer":"12","steps":["5x = 15 × 4.","x = 60 / 5 = 12."]},{"q":"2:3 қатынасында бөлінген 40 кәмпиттің үлкен бөлігінде неше кәмпит бар?","answer":"24","steps":["Барлық үлес 5.","бір үлес 8.","үлкен бөлік 3 × 8 = 24."]}]},{"id":"percent-09","title":"Масштаб","rule":"Масштабта жоспар өлшемі мен нақты өлшем бірдей бірлікпен салыстырылады.","trap":"1:100 масштабтағы 1 см нақты жерде 100 м-ге тең.","problems":[{"q":"1:50 000 картадағы 6 см нақты жерде неше км?","answer":"3","steps":["6 × 50 000 = 300 000 см.","бұл 3 км."]},{"q":"Нақты ұзындығы 8 м қабырға 1:200 жоспарда неше см болады?","answer":"4","steps":["8 м = 800 см.","800 / 200 = 4 см."]}]},{"id":"percent-10","title":"Тура және кері пропорционалдық","rule":"Тура пропорцияда қатынас, кері пропорцияда көбейтінді тұрақты болады.","trap":"Жұмысшы саны екі есе артса, бір жұмыстың уақыты да екі есе артады.","problems":[{"q":"4 дәптер 1 200 ₸. Осындай 7 дәптер қанша теңге?","answer":"2100","steps":["Бір дәптер 300 ₸.","7 × 300 = 2 100 ₸."]},{"q":"Бір жұмысты 6 адам 8 күнде орындайды. Сол қарқынмен 12 адам неше күнде орындайды?","answer":"4","steps":["Адам-күн саны 6 × 8 = 48.","48 / 12 = 4 күн."]}]}],"number":2},{"id":"finance","title":"Қаржылық математикалық есептер","color":"#d8ef96","symbol":"₸","lessons":[{"id":"finance-01","title":"Тауардың бағасы және жеңілдіктер","rule":"Тауар жеңілдігі бастапқы бағаға қолданылады.","trap":"10% жеңілдік төлемді екі есе азайтады.","problems":[{"q":"18 000 ₸ аяқкиімге 20% жеңілдік берілді. Бағасы қанша?","answer":"14400","steps":["18 000 × 0,8 = 14 400.","жеңілдік 3 600 ₸."]},{"q":"Жеңілдік сомасы 3 000 ₸, бастапқы баға 15 000 ₸. Жеңілдік неше пайыз?","answer":"20","steps":["3 000 / 15 000 = 0,2.","бұл 20%."]}]},{"id":"finance-02","title":"Сатып алу құны","rule":"Сатып алу құны — әр тауардың бағасы мен саны көбейтінділерінің қосындысы.","trap":"Сатып алу құны бағаға зат санын қосу арқылы табылады.","problems":[{"q":"4 дәптер 250 ₸-ден және 2 қалам 180 ₸-ден алынды. Барлық төлем қанша?","answer":"1360","steps":["Дәптер: 1 000 ₸.","қалам: 360 ₸.","барлығы 1 360 ₸."]},{"q":"5 000 ₸ беріп, әрқайсысы 650 ₸ болатын 6 зат алдың. Қайтарым қанша?","answer":"1100","steps":["Сатып алу: 6 × 650 = 3 900.","қайтарым 1 100 ₸."]}]},{"id":"finance-03","title":"Табыс, шығын және пайда","rule":"Пайда — табыс пен барлық шығынның айырмасы.","trap":"Пайда барлық табысқа тең.","problems":[{"q":"Кәсіпкер 120 000 ₸ табыс тапты. Шығыны 85 000 ₸. Пайдасы қанша?","answer":"35000","steps":["120 000 − 85 000 = 35 000 ₸.","табыс пен пайда бірдей емес."]},{"q":"40 бұйымның әрқайсысын жасау 500 ₸, сату 750 ₸. Жалпы пайда қанша?","answer":"10000","steps":["Бір бұйымнан 250 ₸.","40 × 250 = 10 000 ₸."]}]},{"id":"finance-04","title":"Отбасылық бюджет","rule":"Бюджет кірісті қажетті шығын, жинақ және басқа мақсаттарға бөледі.","trap":"Шығыс кірістен көп болса, бюджетте артық ақша қалады.","problems":[{"q":"Отбасы кірісі 400 000 ₸. Шығыс 320 000 ₸. Жинақ неше пайыз?","answer":"20","steps":["Жинақ 80 000 ₸.","80 000 / 400 000 × 100 = 20%."]},{"q":"300 000 ₸ бюджеттің 30%-ы азыққа, 20%-ы үйге кетті. Қалғаны қанша?","answer":"150000","steps":["Шығыс үлесі 50%.","қалған 50% — 150 000 ₸."]}]},{"id":"finance-05","title":"Жалақы және сыйақы","rule":"Сыйақы негізгі жалақының белгілі пайызы болса, ол негізгі сомаға қосылады.","trap":"15% сыйақы жалақының 15 есесі болады.","problems":[{"q":"Жалақы 180 000 ₸, сыйақы 15%. Жалпы төлем қанша?","answer":"207000","steps":["Сыйақы 27 000 ₸.","180 000 + 27 000 = 207 000 ₸."]},{"q":"12 сағат жұмысқа сағатына 2 500 ₸ төленеді. Табыс қанша?","answer":"30000","steps":["Сағат санын тарифке көбейт.","12 × 2 500 = 30 000 ₸."]}]},{"id":"finance-06","title":"Банк салымы","rule":"Банк салымының қарапайым пайыздық табысы негізгі сомадан есептеледі.","trap":"Жылдық пайыз ай сайын дәл сол мөлшерде толық есептеледі.","problems":[{"q":"200 000 ₸ салымға бір жылға қарапайым 10% есептелді. Жалпы сома қанша?","answer":"220000","steps":["Табыс 200 000 × 0,1 = 20 000.","жалпы 220 000 ₸."]},{"q":"150 000 ₸ салымнан бір жылда 18 000 ₸ табыс түсті. Жылдық мөлшерлеме неше пайыз?","answer":"12","steps":["18 000 / 150 000 × 100% = 12%."]}]},{"id":"finance-07","title":"Қарапайым және күрделі пайыз","rule":"Қарапайым пайыз бастапқы сомаға, күрделі пайыз өсіп отырған сомаға қолданылады.","trap":"Қарапайым және күрделі пайыз екі жылда әрқашан тең нәтиже береді.","problems":[{"q":"100 000 ₸ жылына 10% күрделі пайызбен 2 жыл өсті. Соңғы сома қанша?","answer":"121000","steps":["Бірінші жыл 110 000.","екінші жыл 110 000 × 1,1 = 121 000 ₸."]},{"q":"100 000 ₸ қарапайым жылдық 10%-бен 2 жыл сақталды. Табыс қанша?","answer":"20000","steps":["Бір жылда 10 000 ₸.","екі жылда 20 000 ₸."]}]},{"id":"finance-08","title":"Несие бойынша есептер","rule":"Несие есебінде негізгі қарыз, пайыз, мерзім және шарттарды бөлек есепке аламыз.","trap":"Айлық төлемді ғана білу несиенің толық құнын анықтауға жеткілікті.","problems":[{"q":"120 000 ₸ қарыз 6 айға тең негізгі төлемдермен, пайызсыз қайтарылады. Ай сайын қанша?","answer":"20000","steps":["Пайыз жоқ.","120 000 / 6 = 20 000 ₸."]},{"q":"200 000 ₸ қарызға бір жылға қарапайым 15% үстеме қосылды. Қайтарылатын сома қанша?","answer":"230000","steps":["Үстеме 30 000.","200 000 + 30 000 = 230 000 ₸."]}]},{"id":"finance-09","title":"Тарифтер мен төлемдер","rule":"Тарифте тұрақты төлем мен пайдалануға байланысты төлемді қосамыз.","trap":"Тұрақты тарифтік төлемді пайдалану ақысына қоспаймыз.","problems":[{"q":"Тариф: 1 500 ₸ және минутына 10 ₸. 80 минутқа төлем қанша?","answer":"2300","steps":["Қосымша шығын 800 ₸.","1 500 + 800 = 2 300 ₸."]},{"q":"Такси 500 ₸ бастапқы ақы және км-ге 120 ₸ алады. 10 км қанша тұрады?","answer":"1700","steps":["500 + 10 × 120 = 1 700 ₸.","бастапқы ақыны да қосамыз."]}]},{"id":"finance-10","title":"Электр, су және жылу шығындары","rule":"Коммуналдық төлем тұтыну көлемі мен бірлік бағасының көбейтіндісіне тәуелді.","trap":"Электр шығыны кВт·сағ орнына тек сағатпен өлшенеді.","problems":[{"q":"180 кВт·сағ электрдің әр кВт·сағ-ы 25 ₸. Төлем қанша?","answer":"4500","steps":["180 × 25 = 4 500 ₸.","бұл есепте бір ғана тұрақты тариф берілген."]},{"q":"12 м³ суға м³-іне 140 ₸, жылуға 3 000 ₸ төленді. Барлығы қанша?","answer":"4680","steps":["Су 12 × 140 = 1 680 ₸.","барлығы 4 680 ₸."]}]},{"id":"finance-11","title":"Жанармай шығыны","rule":"100 км-ге берілген жанармай нормасын қашықтықтың жүздік үлесіне көбейтеміз.","trap":"100 км-ге 8 л жұмсайтын көлік 50 км-ге де 8 л жұмсайды.","problems":[{"q":"Көлік 100 км-ге 8 л жұмсайды. 350 км-ге неше литр керек?","answer":"28","steps":["350 / 100 = 3,5.","3,5 × 8 = 28 л."]},{"q":"100 км-ге 6 л жұмсайтын көлік 500 км жүрді. Литрі 250 ₸ болса, шығын қанша?","answer":"7500","steps":["Көлем 30 л.","құны 30 × 250 = 7 500 ₸."]}]}],"number":3},{"id":"algebra","title":"Алгебра және теңдеулер","color":"#d9aeff","symbol":"x²","lessons":[{"id":"algebra-01","title":"Сандық өрнектер","rule":"Сандық өрнекте амалдардың реті сақталады.","trap":"2 + 3 × 4 = 20.","problems":[{"q":"(36 − 12) ÷ 4 + 7 мәнін тап.","answer":"13","steps":["Жақша 24.","24 / 4 + 7 = 6 + 7 = 13."]},{"q":"5² + 3 × 4 − 8 мәнін тап.","answer":"29","steps":["25 + 12 − 8 = 29.","дәреже мен көбейтуді алдымен орында."]}]},{"id":"algebra-02","title":"Әріпті өрнектер","rule":"Әріпті өрнектің мәні әріптің берілген мәнін орнына қою арқылы табылады.","trap":"a = 3 болса, 2a = 23.","problems":[{"q":"a = 4, b = −2 болса, 3a − 2b мәнін тап.","answer":"16","steps":["3 × 4 − 2 × (−2) = 12 + 4 = 16."]},{"q":"x = 5 болса, x² − 3x + 2 мәнін тап.","answer":"12","steps":["25 − 15 + 2 = 12.","x орнына 5 қойылды."]}]},{"id":"algebra-03","title":"Формула бойынша есептеу","rule":"Формуладағы барлық шамалар сәйкес өлшем бірліктерімен қойылады.","trap":"Формулаға мән қойғанда көбейту таңбасын қосуға ауыстыруға болады.","problems":[{"q":"S = a × b формуласында a = 7, b = 9. S-ті тап.","answer":"63","steps":["Берілген мәндерді қой.","S = 7 × 9 = 63."]},{"q":"C = 2πr, π = 3, r = 5 болса, C-ні тап.","answer":"30","steps":["C = 2 × 3 × 5.","нәтижесі 30."]}]},{"id":"algebra-04","title":"Сызықтық теңдеулер","rule":"Сызықтық теңдеудің екі жағына бірдей амал қолдансақ, теңдік сақталады.","trap":"3x = 12 теңдеуінің шешімі 36.","problems":[{"q":"3x + 7 = 28 теңдеуін шеш.","answer":"7","steps":["3x = 21.","x = 7."]},{"q":"5(x − 2) = 35 теңдеуін шеш.","answer":"9","steps":["x − 2 = 7.","x = 9."]}]},{"id":"algebra-05","title":"Квадрат теңдеулердің қарапайым түрлері","rule":"Квадрат теңдеуде түбірді бастапқы теңдеуге қойып тексеру пайдалы.","trap":"x² = 9 теңдеуінің жалғыз түбірі 3.","problems":[{"q":"x² = 49 теңдеуінің оң түбірін жаз.","answer":"7","steps":["7² = 49.","оң түбір 7, ал екінші түбір −7."]},{"q":"x² − 5x + 6 = 0 теңдеуінің кіші түбірін тап.","answer":"2","steps":["(x − 2)(x − 3) = 0.","түбірлер 2 және 3."]}]},{"id":"algebra-06","title":"Теңдеулер жүйесі","rule":"Жүйе шешімі екі теңдеуді де бір уақытта қанағаттандырады.","trap":"Жүйені шешкенде екі теңдеудің біреуі ғана орындалса жеткілікті.","problems":[{"q":"x + y = 11, x − y = 3. x-ті тап.","answer":"7","steps":["Теңдеулерді қос: 2x = 14.","x = 7."]},{"q":"2x + y = 13, x + y = 8. y-ті тап.","answer":"3","steps":["Азайтсақ x = 5.","y = 8 − 5 = 3."]}]},{"id":"algebra-07","title":"Теңсіздіктер","rule":"Теңсіздікті теріс санға көбейткенде не бөлгенде оның белгісі кері өзгереді.","trap":"Теңсіздіктің екі жағын теріс санға бөлгенде белгі өзгермейді.","problems":[{"q":"2x + 3 < 11 шартын қанағаттандыратын ең үлкен бүтін x-ті тап.","answer":"3","steps":["2x < 8.","x < 4, ең үлкен бүтін — 3."]},{"q":"−3x ≥ 12 шартын қанағаттандыратын ең үлкен x-ті тап.","answer":"-4","steps":["Теріс санға бөлгенде белгі өзгереді.","x ≤ −4."]}]},{"id":"algebra-08","title":"Модульмен берілген есептер","rule":"Модуль санның нөлден қашықтығын көрсетеді және теріс болмайды.","trap":"Теріс санның модулі де теріс болады.","problems":[{"q":"x = −8 болса, модулінің мәнін тап.","answer":"8","steps":["−8 саны нөлден 8 бірлікке алыс.","модулі 8."]},{"q":"x − 3 өрнегінің модулі 5-ке тең. Шешімдердің үлкенін тап.","answer":"8","steps":["x − 3 = 5 не −5.","x = 8 не −2, үлкені 8."]}]},{"id":"algebra-09","title":"Белгісіз шаманы табу","rule":"Белгісіз шаманы табу үшін байланысқа сәйкес кері амал қолданамыз.","trap":"Белгісіз қосылғышты табу үшін қосындыға белгілі қосылғышты қосамыз.","problems":[{"q":"□ ÷ 6 + 4 = 13. Белгісіз санды тап.","answer":"54","steps":["□ / 6 = 9.","□ = 54."]},{"q":"Белгісіз санды 4-ке көбейтіп, 9-ды азайтқанда 31 шықты. Сан қандай?","answer":"10","steps":["4x − 9 = 31.","4x = 40, x = 10."]}]},{"id":"algebra-10","title":"Мәтіндік есепті теңдеу арқылы шығару","rule":"Мәтіндік есепте белгісізді белгілеп, шартты теңдеуге айналдырамыз.","trap":"Мәтіндік есептің теңдеуінде өлшем бірлігін елемеуге болады.","problems":[{"q":"Бір санның үш есесіне 5 қосқанда 41 шығады. Санды тап.","answer":"12","steps":["3x + 5 = 41.","3x = 36, x = 12."]},{"q":"Екі санның қосындысы 26, үлкені кішісінен 8 артық. Кіші санды тап.","answer":"9","steps":["x + x + 8 = 26.","2x = 18, x = 9."]}]}],"number":4},{"id":"motion","title":"Қозғалыс есептері","color":"#80cddd","symbol":"↗","lessons":[{"id":"motion-01","title":"Жылдамдық, уақыт және қашықтық","rule":"Қашықтық жылдамдық пен уақыттың көбейтіндісіне тең.","trap":"Қашықтықты табу үшін жылдамдықты уақытқа бөлеміз.","problems":[{"q":"Автобус 72 км/сағ жылдамдықпен 2,5 сағат жүрді. Қашықтық неше км?","answer":"180","steps":["s = v × t.","72 × 2,5 = 180 км."]},{"q":"210 км жолды 70 км/сағ жылдамдықпен неше сағатта өтеді?","answer":"3","steps":["t = s / v.","210 / 70 = 3 сағат."]}]},{"id":"motion-02","title":"Бір-біріне қарсы қозғалыс","rule":"Қарама-қарсы қозғалыста жақындау жылдамдығы екі жылдамдықтың қосындысы болады.","trap":"Қарсы қозғалыста жылдамдықтар міндетті түрде азайтылады.","problems":[{"q":"Арасы 300 км екі көлік 60 және 40 км/сағ жылдамдықпен бір-біріне қарсы шықты. Неше сағатта кездеседі?","answer":"3","steps":["Жақындау жылдамдығы 100 км/сағ.","300 / 100 = 3 сағ."]},{"q":"4 және 5 км/сағ жылдамдықтағы жаяулар 2 сағатта бірге неше км жақындайды?","answer":"18","steps":["Бір сағатта 9 км.","2 × 9 = 18 км."]}]},{"id":"motion-03","title":"Бір бағыттағы қозғалыс","rule":"Бір бағыттағы салыстырмалы жылдамдық екі жылдамдықтың айырмасына тең.","trap":"Бір бағыттағы қозғалыста аралық өзгерісі жылдамдықтар қосындысымен анықталады.","problems":[{"q":"Бір бағыттағы екі көліктің жылдамдықтары 80 және 60 км/сағ. 3 сағатта аралық неше км-ге өзгереді?","answer":"60","steps":["Айырма 20 км/сағ.","3 сағатта 60 км."]},{"q":"5 және 3 км/сағ жылдамдықпен бір нүктеден бір бағытта шыққан жаяулардың 4 сағаттан кейінгі арасы қанша?","answer":"8","steps":["Салыстырмалы жылдамдық 2 км/сағ.","2 × 4 = 8 км."]}]},{"id":"motion-04","title":"Қуып жету есептері","rule":"Қуып жету уақыты бастапқы аралықты салыстырмалы жылдамдыққа бөлгенге тең.","trap":"Қуып жету уақытын табу үшін бастапқы аралықты жылдамдықтар қосындысына бөлеміз.","problems":[{"q":"Алдыңғы көлік 60, артқысы 80 км/сағ жылдамдықпен жүрді. Аралық 40 км. Неше сағатта қуып жетеді?","answer":"2","steps":["Артқы көлік сағатына 20 км жақындайды.","40 / 20 = 2 сағ."]},{"q":"Жаяу 5 км/сағ жылдамдықпен 2 сағат бұрын шықты. 15 км/сағ велосипедші шыққаннан кейін неше сағатта жетеді?","answer":"1","steps":["Бастапқы аралық 10 км.","салыстырмалы жылдамдық 10 км/сағ, уақыт 1 сағ."]}]},{"id":"motion-05","title":"Өзен ағысымен және ағысқа қарсы қозғалыс","rule":"Ағыспен жылдамдыққа ағыс жылдамдығы қосылады, ағысқа қарсы одан алынады.","trap":"Ағысқа қарсы жылдамдық өз жылдамдық пен ағыс жылдамдығының қосындысы болады.","problems":[{"q":"Қайықтың өз жылдамдығы 12, ағыс 3 км/сағ. Ағыспен 2 сағатта неше км жүреді?","answer":"30","steps":["Ағыспен жылдамдық 15 км/сағ.","қашықтық 30 км."]},{"q":"Қайық ағыспен 18, қарсы 12 км/сағ жүреді. Ағыс жылдамдығы қанша?","answer":"3","steps":["Қос жылдамдық айырмасы 6.","ағыс жылдамдығы 6 / 2 = 3 км/сағ."]}]},{"id":"motion-06","title":"Орташа жылдамдық","rule":"Орташа жылдамдық барлық жолды барлық уақытқа бөлу арқылы табылады.","trap":"Әртүрлі уақыттағы қозғалыста орташа жылдамдық әрқашан жылдамдықтардың жай орташа мәніне тең.","problems":[{"q":"Көлік 60 км-ді 30 км/сағ, келесі 60 км-ді 60 км/сағ жылдамдықпен өтті. Орташа жылдамдық қанша?","answer":"40","steps":["Жалпы жол 120 км.","уақыт 2 + 1 = 3 сағ.","120 / 3 = 40 км/сағ."]},{"q":"Көлік 2 сағат 50 км/сағ, 1 сағат 80 км/сағ жылдамдықпен жүрді. Орташа жылдамдық қанша?","answer":"60","steps":["Жол 100 + 80 = 180 км.","уақыт 3 сағат.","орташа 60 км/сағ."]}]},{"id":"motion-07","title":"Пойыздың көпірден өтуі","rule":"Пойыз көпірден толық өту үшін пойыз бен көпір ұзындықтарының қосындысындай жол жүреді.","trap":"Көпірден толық өту жолы тек көпірдің ұзындығына тең.","problems":[{"q":"Ұзындығы 200 м пойыз 400 м көпірден 20 м/с жылдамдықпен өтті. Неше секунд керек?","answer":"30","steps":["Толық жол 200 + 400 = 600 м.","600 / 20 = 30 с."]},{"q":"Ұзындығы 150 м пойыз бағаннан 10 секундта өтті. Жылдамдығы неше м/с?","answer":"15","steps":["Бағаннан өткен жол пойыз ұзындығына тең.","150 / 10 = 15 м/с."]}]},{"id":"motion-08","title":"Жаяу жүргінші мен велосипедші","rule":"Жаяу мен велосипедші есебінде уақытты бірдей бірлікке келтіреміз.","trap":"Бірдей жолда жылдамдық артса, уақыт та артады.","problems":[{"q":"Велосипедші 18 км-ді 1 сағатта өтті. Жаяу 6 км/сағ жылдамдықпен осы жолға неше сағат жұмсайды?","answer":"3","steps":["Бірдей жол — 18 км.","18 / 6 = 3 сағат."]},{"q":"Жаяу 5 км/сағ жылдамдықпен 40 минут жүрді. Велосипедші 20 км/сағ жылдамдықпен осы жолды неше минутта өтеді?","answer":"10","steps":["Велосипедші 4 есе жылдам.","оған 40 / 4 = 10 минут қажет."]}]},{"id":"motion-09","title":"Кесте және график бойынша қозғалыс","rule":"Жол–уақыт графигіндегі кесіндінің көлбеулігі жылдамдықты көрсетеді.","trap":"Жол–уақыт графигіндегі көлденең кесінді жоғары жылдамдықты білдіреді.","problems":[{"q":"Кестеде t = 0, 1, 2 сағ; s = 0, 45, 90 км. Тұрақты жылдамдықты тап.","answer":"45","steps":["Бір сағаттағы жол өсімі 45 км.","жылдамдық 45 км/сағ."]},{"q":"Жол графигінде t = 2 және t = 3 сағатта s = 100 км. Осы аралықтағы жылдамдық қандай?","answer":"0","steps":["Бір сағатта қашықтық өзгермеген.","дене тоқтап тұр, жылдамдық 0."]}]}],"number":5},{"id":"work","title":"Жұмыс және өнімділік","color":"#f1b69b","symbol":"⚙","lessons":[{"id":"work-01","title":"Бірлескен жұмыс","rule":"Бірлескен өнімділік жеке өнімділіктердің қосындысына тең.","trap":"Бірлескен жұмыс уақыты жеке уақыттардың қосындысына тең.","problems":[{"q":"Бір шебер жұмысты 6 сағатта, екіншісі 3 сағатта бітіреді. Бірге неше сағат қажет?","answer":"2","steps":["Өнімділік: 1/6 + 1/3 = 1/2.","уақыт 1 / (1/2) = 2 сағат."]},{"q":"Екі құрылғы жұмысты жеке 4 және 12 сағатта орындайды. Бірге неше сағатта бітіреді?","answer":"3","steps":["1/4 + 1/12 = 1/3.","толық жұмысқа 3 сағат керек."]}]},{"id":"work-02","title":"Жұмысшының өнімділігі","rule":"Өнімділік — бір уақыт бірлігінде орындалатын жұмыс мөлшері.","trap":"Өнімділікті табу үшін жұмыс мөлшерін уақытқа көбейтеміз.","problems":[{"q":"Жұмысшы 5 сағатта 120 бөлшек жасады. Бір сағаттағы өнімділігі қанша?","answer":"24","steps":["Өнімділік = жұмыс / уақыт.","120 / 5 = 24 бөлшек/сағ."]},{"q":"Сағатына 18 бөлшек жасайтын жұмысшы 7 сағатта неше бөлшек жасайды?","answer":"126","steps":["Жұмыс = өнімділік × уақыт.","18 × 7 = 126."]}]},{"id":"work-03","title":"Бір жұмысты орындау уақыты","rule":"Уақыт жұмыс көлемін өнімділікке бөлу арқылы табылады.","trap":"Өнімділік екі есе артса, бір жұмыстың уақыты өзгермейді.","problems":[{"q":"240 бөлшекті сағатына 30 бөлшек жасайтын құрылғы неше сағатта өндіреді?","answer":"8","steps":["t = A / p.","240 / 30 = 8 сағат."]},{"q":"Сағатына 45 бет басатын принтер 135 бетті неше сағатта басады?","answer":"3","steps":["135 / 45 = 3.","уақыт 3 сағат."]}]},{"id":"work-04","title":"Құбырлар арқылы ыдысты толтыру","rule":"Екі құбыр бірге толтырса, олардың толтыру жылдамдықтары қосылады.","trap":"Бірге ашылған толтыру құбырларының өнімділіктері азайтылады.","problems":[{"q":"Бір құбыр бассейнді 8, екіншісі 8 сағатта толтырады. Бірге неше сағатта толтырады?","answer":"4","steps":["1/8 + 1/8 = 1/4.","бассейн 4 сағатта толады."]},{"q":"Минутына 12 л және 8 л құятын екі құбыр 100 л ыдысты неше минутта толтырады?","answer":"5","steps":["Жалпы жылдамдық 20 л/мин.","100 / 20 = 5 мин."]}]},{"id":"work-05","title":"Ыдысты босату","rule":"Су кіріп және шығып тұрса, таза толтыру жылдамдығы кіріс пен шығыс айырмасына тең.","trap":"Суды ағызатын құбыр ашылса, ыдыс міндетті түрде жылдамырақ толады.","problems":[{"q":"Ыдысқа минутына 15 л құйылып, 5 л ағады. Бос 120 л ыдыс неше минутта толады?","answer":"12","steps":["Таза жылдамдық 15 − 5 = 10 л/мин.","120 / 10 = 12 мин."]},{"q":"180 л су минутына 12 л жылдамдықпен ағады. Ыдыс неше минутта босайды?","answer":"15","steps":["180 / 12 = 15.","басқа кіріс ағыны жоқ."]}]},{"id":"work-06","title":"Өнім өндіру және жинау","rule":"Өндіріс есебінде өнімділік пен уақыттың көбейтіндісі жалпы өнімді береді.","trap":"Бір құрылғының өнімділігі барлық құрылғының жалпы жұмысына әрқашан тең.","problems":[{"q":"Конвейер минутына 25 қап жасайды. 12 минутта неше қап шығады?","answer":"300","steps":["25 × 12 = 300 қап.","қарқын тұрақты."]},{"q":"3 бірдей комбайн 2 сағатта 36 га жинады. Бір комбайнның сағаттық өнімділігі қанша га?","answer":"6","steps":["Барлығы 6 комбайн-сағат.","36 / 6 = 6 га/сағ."]}]},{"id":"work-07","title":"Бірнеше адамның бірлесіп жұмыс істеуі","rule":"Бірдей жұмысшылардың жалпы өнімділігі адам санына тура пропорционал.","trap":"Жұмысшы саны артқанда бір жұмыстың жалпы адам-күн мөлшері міндетті түрде артады.","problems":[{"q":"4 жұмысшы 6 күнде жұмысты бітіреді. 8 жұмысшы сол қарқынмен неше күнде бітіреді?","answer":"3","steps":["Жұмыс көлемі 24 адам-күн.","24 / 8 = 3 күн."]},{"q":"Бір жұмысты 3 адам 10 күнде істейді. 5 адамға неше күн керек?","answer":"6","steps":["Жалпы еңбек 30 адам-күн.","30 / 5 = 6 күн."]}]}],"number":6},{"id":"geometry","title":"Геометрия","color":"#aca4ff","symbol":"△","lessons":[{"id":"geometry-01","title":"Нүкте, түзу және кесінді","rule":"Кесіндінің ұзындығы бір түзудегі бөліктер ұзындықтарының қосындысына тең.","trap":"Кесіндінің ұзындығы теріс болуы мүмкін.","problems":[{"q":"B нүктесі A мен C арасында. AB = 7 см, BC = 5 см. AC неше см?","answer":"12","steps":["B екі нүктенің арасында.","AC = 7 + 5 = 12 см."]},{"q":"AC = 20 см, AB = 8 см, B нүктесі A мен C арасында. BC неше см?","answer":"12","steps":["BC = AC − AB.","20 − 8 = 12 см."]}]},{"id":"geometry-02","title":"Бұрыштар","rule":"Сыбайлас бұрыштар қосындысы 180°, вертикаль бұрыштар тең болады.","trap":"Сыбайлас бұрыштардың қосындысы 90° болады.","problems":[{"q":"Сыбайлас бұрыштардың бірі 65°. Екіншісі неше градус?","answer":"115","steps":["Қосынды 180°.","180 − 65 = 115°."]},{"q":"Тік бұрыш екі бөлікке бөлінді. Бірі 28°. Екіншісі қанша градус?","answer":"62","steps":["Тік бұрыш 90°.","90 − 28 = 62°."]}]},{"id":"geometry-03","title":"Үшбұрыштар","rule":"Үшбұрыштың ішкі бұрыштарының қосындысы 180° болады.","trap":"Үшбұрыштың ішкі бұрыштарының қосындысы 360°.","problems":[{"q":"Үшбұрыштың екі бұрышы 50° және 60°. Үшіншісі неше градус?","answer":"70","steps":["180 − 50 − 60 = 70°.","барлық бұрыштың қосындысы 180°."]},{"q":"Теңбүйірлі үшбұрыштың төбе бұрышы 40°. Табан бұрышы неше градус?","answer":"70","steps":["Қалған бұрыштардың қосындысы 140°.","әрқайсысы 140 / 2 = 70°."]}]},{"id":"geometry-04","title":"Төртбұрыштар","rule":"Кез келген дөңес төртбұрыштың ішкі бұрыштарының қосындысы 360° болады.","trap":"Кез келген төртбұрыштың барлық бұрышы тік болады.","problems":[{"q":"Төртбұрыштың үш бұрышы 80°, 90°, 100°. Төртіншісі неше градус?","answer":"90","steps":["Үш бұрыш қосындысы 270°.","360 − 270 = 90°."]},{"q":"Төртбұрыштың үш қабырғасы 4, 6, 7 см, периметрі 22 см. Төртінші қабырғасы неше см?","answer":"5","steps":["Белгілі ұзындықтар қосындысы 17 см.","22 − 17 = 5 см."]}]},{"id":"geometry-05","title":"Шаршы және тіктөртбұрыш","rule":"Тіктөртбұрыш ауданы ab, шаршы ауданы a² формулаларымен табылады.","trap":"Тіктөртбұрыш ауданы 2(a + b) болады.","problems":[{"q":"Ұзындығы 9 м, ені 4 м еденнің ауданы неше м²?","answer":"36","steps":["S = a × b.","9 × 4 = 36 м²."]},{"q":"Периметрі 28 см шаршының ауданы неше см²?","answer":"49","steps":["Қабырғасы 28 / 4 = 7.","ауданы 7² = 49 см²."]}]},{"id":"geometry-06","title":"Параллелограмм және ромб","rule":"Параллелограмм ауданы табан мен сол табанға түсірілген биіктіктің көбейтіндісіне тең.","trap":"Ромб ауданы диагональдарының қосындысына тең.","problems":[{"q":"Параллелограмм табаны 12 см, биіктігі 5 см. Ауданы қанша см²?","answer":"60","steps":["S = ah.","12 × 5 = 60 см²."]},{"q":"Ромб диагональдары 10 см және 8 см. Ауданы неше см²?","answer":"40","steps":["S = d₁d₂ / 2.","10 × 8 / 2 = 40 см²."]}]},{"id":"geometry-07","title":"Трапеция","rule":"Трапеция ауданы табандар қосындысының жартысын биіктікке көбейту арқылы табылады.","trap":"Трапеция ауданы табандар айырмасы мен биіктік көбейтіндісіне тең.","problems":[{"q":"Трапеция табандары 6 және 10 см, биіктігі 4 см. Ауданы қанша см²?","answer":"32","steps":["S = (6 + 10) × 4 / 2.","нәтиже 32 см²."]},{"q":"Трапеция ауданы 45 см², табандары 6 және 9 см. Биіктігі неше см?","answer":"6","steps":["45 = 15h / 2.","h = 90 / 15 = 6 см."]}]},{"id":"geometry-08","title":"Периметр","rule":"Периметр — фигура шекарасындағы барлық қабырға ұзындықтарының қосындысы.","trap":"Периметр шаршы метрмен өлшенеді.","problems":[{"q":"Қабырғалары 5, 7, 9 см үшбұрыштың периметрі неше см?","answer":"21","steps":["P = 5 + 7 + 9.","периметр 21 см."]},{"q":"Ұзындығы 12 м, ені 8 м бақтың қоршауына неше м материал керек?","answer":"40","steps":["P = 2(12 + 8).","қоршау ұзындығы 40 м."]}]},{"id":"geometry-09","title":"Фигуралардың ауданы","rule":"Құрама фигураның ауданын бөліктерге бөліп немесе артық бөлігін алып есептейміз.","trap":"Үшбұрыш ауданы әрқашан табан мен биіктік көбейтіндісіне тең.","problems":[{"q":"10 × 8 м тіктөртбұрыштан 3 × 2 м бұрыш қиылды. Қалған аудан неше м²?","answer":"74","steps":["Бүтін аудан 80 м².","кесілгені 6 м².","қалғаны 74 м²."]},{"q":"Табаны 14 см, биіктігі 6 см үшбұрыштың ауданы неше см²?","answer":"42","steps":["S = ah / 2.","14 × 6 / 2 = 42 см²."]}]},{"id":"geometry-10","title":"Шеңбер ұзындығы","rule":"Шеңбер ұзындығы C = 2πr немесе C = πd арқылы табылады.","trap":"Шеңбер ұзындығы πr² формуласына тең.","problems":[{"q":"Диаметрі 10 см шеңбердің ұзындығын тап. π = 3,14.","answer":"31.4","steps":["C = πd.","3,14 × 10 = 31,4 см."]},{"q":"Радиусы 7 см шеңбердің ұзындығын тап. π = 22/7.","answer":"44","steps":["C = 2 × (22/7) × 7.","нәтиже 44 см."]}]},{"id":"geometry-11","title":"Дөңгелек ауданы","rule":"Дөңгелек ауданы S = πr²; радиустың квадраты алынады.","trap":"Диаметрді радиус орнына қойсақ, аудан өзгермейді.","problems":[{"q":"Радиусы 5 см дөңгелектің ауданын тап. π = 3,14.","answer":"78.5","steps":["r² = 25.","3,14 × 25 = 78,5 см²."]},{"q":"Диаметрі 8 см дөңгелектің ауданын тап. π = 3.","answer":"48","steps":["Радиус 4 см.","S = 3 × 4² = 48 см²."]}]},{"id":"geometry-12","title":"Пифагор теоремасы","rule":"Тікбұрышты үшбұрышта катеттер квадраттарының қосындысы гипотенуза квадратына тең.","trap":"Пифагор теоремасы барлық үшбұрышқа бірдей қолданылады.","problems":[{"q":"Катеттері 6 және 8 см үшбұрыштың гипотенузасы неше см?","answer":"10","steps":["c² = 36 + 64 = 100.","c = 10 см."]},{"q":"Гипотенузасы 13 см, бір катеті 5 см. Екінші катеті неше см?","answer":"12","steps":["b² = 169 − 25 = 144.","b = 12 см."]}]},{"id":"geometry-13","title":"Ұқсас фигуралар","rule":"Ұқсас фигуралардың ұзындықтары k есе, аудандары k² есе өзгереді.","trap":"Қабырғалар 3 есе өссе, аудан да 3 есе өседі.","problems":[{"q":"Ұқсас үшбұрыштардың сәйкес қабырғалары 4 және 12 см. Үлкейту коэффициенті қандай?","answer":"3","steps":["k = 12 / 4.","үлкейту коэффициенті 3."]},{"q":"Фигура 2 есе үлкейтілді. Бастапқы ауданы 15 см². Жаңа ауданы неше см²?","answer":"60","steps":["Аудан коэффициенті 2² = 4.","15 × 4 = 60 см²."]}]},{"id":"geometry-14","title":"Координаталық жазықтық","rule":"Координаталық жазықтықта нүкте (x; y) жұбымен беріледі.","trap":"Координата жұбында бірінші сан y координатасын білдіреді.","problems":[{"q":"A(−2; 3), B(4; 3) нүктелерінің арақашықтығы неше бірлік?","answer":"6","steps":["y координаталары бірдей.","қашықтық 4 − (−2) = 6."]},{"q":"A(2; −1) нүктесін жоғары 5 бірлік жылжыттық. Жаңа y координатасы қандай?","answer":"4","steps":["x өзгермейді.","y = −1 + 5 = 4."]}]},{"id":"geometry-15","title":"Куб және параллелепипед","rule":"Куб көлемі a³, тікбұрышты параллелепипед көлемі abc.","trap":"Куб көлемі 6a² формуласына тең.","problems":[{"q":"Қабырғасы 4 см кубтың көлемі неше см³?","answer":"64","steps":["V = a³.","4 × 4 × 4 = 64 см³."]},{"q":"Өлшемдері 3, 5, 8 см қораптың көлемі қанша см³?","answer":"120","steps":["V = abc.","3 × 5 × 8 = 120 см³."]}]},{"id":"geometry-16","title":"Призма және пирамида","rule":"Призма көлемі табан ауданы мен биіктік көбейтіндісі; пирамидада оның үштен бірі алынады.","trap":"Табаны мен биіктігі бірдей призма мен пирамиданың көлемдері тең.","problems":[{"q":"Табан ауданы 18 см², биіктігі 7 см призманың көлемі неше см³?","answer":"126","steps":["V = Sₜh.","18 × 7 = 126 см³."]},{"q":"Табан ауданы 36 см², биіктігі 9 см пирамиданың көлемі неше см³?","answer":"108","steps":["V = Sₜh / 3.","36 × 9 / 3 = 108 см³."]}]},{"id":"geometry-17","title":"Цилиндр, конус және шар","rule":"Цилиндр көлемі πr²h, конус көлемі πr²h/3, шар көлемі 4πr³/3.","trap":"Конустың көлемі табаны мен биіктігі бірдей цилиндр көлеміне тең.","problems":[{"q":"Радиусы 3 см, биіктігі 5 см цилиндрдің көлемі қанша? π = 3.","answer":"135","steps":["V = 3 × 3² × 5.","нәтиже 135 см³."]},{"q":"Радиусы 3 см шардың көлемі қанша? π = 3.","answer":"108","steps":["V = 4 × 3 × 27 / 3.","нәтиже 108 см³."]}]},{"id":"geometry-18","title":"Көлем және бет ауданы","rule":"Көлем кеңістікті, бет ауданы дененің сыртқы беттерінің жалпы ауданын өлшейді.","trap":"Бет ауданы текше сантиметрмен өлшенеді.","problems":[{"q":"Қабырғасы 5 см кубтың толық бет ауданы неше см²?","answer":"150","steps":["Бір беті 25 см².","6 × 25 = 150 см²."]},{"q":"Өлшемдері 2, 3, 4 см қораптың толық бет ауданы неше см²?","answer":"52","steps":["S = 2(ab + bc + ac).","2(6 + 12 + 8) = 52 см²."]}]}],"number":7},{"id":"units","title":"Өлшем бірліктері","color":"#8dd4b7","symbol":"㎥","lessons":[{"id":"units-01","title":"Ұзындық бірліктері","rule":"1 км = 1 000 м; 1 м = 100 см.","trap":"1 км = 100 м.","problems":[{"q":"3,5 км-ді метрге айналдыр.","answer":"3500","steps":["3,5 × 1 000.","нәтиже 3 500 м."]},{"q":"450 см неше метр?","answer":"4.5","steps":["450 / 100.","нәтиже 4,5 м."]}]},{"id":"units-02","title":"Аудан бірліктері","rule":"Аудан бірлігінде ұзындыққа арналған ауысу коэффициенті квадратталады.","trap":"1 м² = 100 см².","problems":[{"q":"2,5 м² неше см²?","answer":"25000","steps":["1 м² = 10 000 см².","2,5 × 10 000 = 25 000."]},{"q":"350 дм² неше м²?","answer":"3.5","steps":["1 м² = 100 дм².","350 / 100 = 3,5 м²."]}]},{"id":"units-03","title":"Көлем бірліктері","rule":"Көлем бірлігінде ұзындыққа арналған ауысу коэффициенті кубталады.","trap":"1 м³ = 1 000 см³.","problems":[{"q":"0,004 м³ неше см³?","answer":"4000","steps":["1 м³ = 1 000 000 см³.","нәтиже 4 000 см³."]},{"q":"2 500 см³ неше дм³?","answer":"2.5","steps":["1 дм³ = 1 000 см³.","2 500 / 1 000 = 2,5."]}]},{"id":"units-04","title":"Масса бірліктері","rule":"1 тонна = 1 000 кг; 1 кг = 1 000 г.","trap":"1 тонна = 100 кг.","problems":[{"q":"2,75 кг неше грамм?","answer":"2750","steps":["2,75 × 1 000.","нәтиже 2 750 г."]},{"q":"3 500 кг неше тонна?","answer":"3.5","steps":["3 500 / 1 000.","нәтиже 3,5 т."]}]},{"id":"units-05","title":"Уақыт бірліктері","rule":"1 сағат = 60 минут; 1 минут = 60 секунд.","trap":"1 сағат 30 минут = 1,3 сағат.","problems":[{"q":"2 сағат 35 минут неше минут?","answer":"155","steps":["2 × 60 = 120.","120 + 35 = 155 минут."]},{"q":"5 400 секунд неше сағат?","answer":"1.5","steps":["1 сағат = 3 600 секунд.","5 400 / 3 600 = 1,5."]}]},{"id":"units-06","title":"Жылдамдық бірліктері","rule":"Км/сағ-ты м/с-қа айналдыру үшін 3,6-ға бөлеміз.","trap":"36 км/сағ = 36 м/с.","problems":[{"q":"72 км/сағ неше м/с?","answer":"20","steps":["72 / 3,6 = 20 м/с.","бірліктерді толық қысқартуға да болады."]},{"q":"15 м/с неше км/сағ?","answer":"54","steps":["Кері түрлендіруде 3,6-ға көбейт.","15 × 3,6 = 54 км/сағ."]}]},{"id":"units-07","title":"Литр мен текше метр","rule":"1 м³ = 1 000 л; 1 л = 1 дм³.","trap":"1 литр = 1 м³.","problems":[{"q":"2,4 м³ неше литр?","answer":"2400","steps":["2,4 × 1 000.","нәтиже 2 400 л."]},{"q":"750 л неше м³?","answer":"0.75","steps":["750 / 1 000.","нәтиже 0,75 м³."]}]},{"id":"units-08","title":"Гектар мен шаршы метр","rule":"1 гектар = 10 000 м²; 1 ар = 100 м².","trap":"1 гектар = 100 м².","problems":[{"q":"3,2 га неше м²?","answer":"32000","steps":["3,2 × 10 000.","нәтиже 32 000 м²."]},{"q":"45 000 м² неше гектар?","answer":"4.5","steps":["45 000 / 10 000.","нәтиже 4,5 га."]}]},{"id":"units-09","title":"Өлшем бірліктерін түрлендіру","rule":"Есепте шамаларды қоспас бұрын бірдей өлшем бірлігіне келтіреміз.","trap":"2 м мен 30 см қосындысы 32 м.","problems":[{"q":"2 м 35 см мен 85 см қосындысын сантиметрмен жаз.","answer":"320","steps":["2 м 35 см = 235 см.","235 + 85 = 320 см."]},{"q":"1,5 кг-нан 350 г алынды. Қалған масса неше грамм?","answer":"1150","steps":["1,5 кг = 1 500 г.","1 500 − 350 = 1 150 г."]}]}],"number":8},{"id":"data","title":"Статистика және диаграммалар","color":"#8cd4f0","symbol":"▥","lessons":[{"id":"data-01","title":"Кестелерді оқу","rule":"Кестені оқығанда жол, баған атаулары мен өлшем бірлігін тексереміз.","trap":"Кестедегі өлшем бірлігін оқудың қажеті жоқ.","problems":[{"q":"Кесте: дүйсенбі 12, сейсенбі 18, сәрсенбі 20 билет. Барлығы қанша?","answer":"50","steps":["Жолдардағы мәндерді қос.","12 + 18 + 20 = 50."]},{"q":"Кесте: А дүкені 35, B дүкені 28 кітап сатты. Айырмасы қанша?","answer":"7","steps":["35 − 28 = 7 кітап.","екі мән бірдей бірлікпен берілген."]}]},{"id":"data-02","title":"Бағандық диаграмма","rule":"Баған биіктігі мәнді, ал осьтегі шкала оның өлшемін көрсетеді.","trap":"Бағандық диаграмманың ең биік бағаны әрқашан ең кіші мәнді көрсетеді.","problems":[{"q":"Диаграмма мәндері: A = 24, B = 36, C = 30. Ең үлкен мен ең кішінің айырмасы қанша?","answer":"12","steps":["Ең үлкені 36.","ең кішісі 24.","айырмасы 12."]},{"q":"Бағандардағы төрт мән: 10, 15, 25, 30. Алғашқы екеуінің қосындысы қанша?","answer":"25","steps":["Бірінші және екінші бағанды оқы.","10 + 15 = 25."]}]},{"id":"data-03","title":"Дөңгелек диаграмма","rule":"Дөңгелек диаграммада толық шеңбер 360° және 100%-ға сәйкес келеді.","trap":"180° сектор толықтың 25%-ын көрсетеді.","problems":[{"q":"Дөңгелек диаграмманың 90° секторы барлықтың неше пайызы?","answer":"25","steps":["90 / 360 = 1/4.","бұл 25%."]},{"q":"200 адамның 40%-ына сәйкес сектор неше адамды көрсетеді?","answer":"80","steps":["200 × 0,4 = 80.","сектор көлемі 144° болады."]}]},{"id":"data-04","title":"Сызықтық график","rule":"Сызықтық график мәннің уақыт бойынша өзгерісін көрсетеді.","trap":"Сызықтық графикте көлденең кесінді міндетті түрде нөл мәнді білдіреді.","problems":[{"q":"Күндік температуралар: 8, 12, 15, 10°C. Біріншіден үшінші күнге дейінгі өсім қанша?","answer":"7","steps":["Үшінші күн 15°C, бірінші күн 8°C.","өсім 7°C."]},{"q":"Графикте 10:00-де 40, 12:00-де 70 дана өнім бар. Екі сағаттағы өсім қанша?","answer":"30","steps":["70 − 40 = 30 дана.","уақыт аралығы 2 сағат."]}]},{"id":"data-05","title":"Орташа арифметикалық","rule":"Орташа арифметикалық — барлық мән қосындысының олардың санына қатынасы.","trap":"Орташа мәнді табу үшін тек ең үлкен екі санды қосамыз.","problems":[{"q":"6, 8, 9, 13 сандарының орташа мәнін тап.","answer":"9","steps":["Қосынды 36.","36 / 4 = 9."]},{"q":"Үш тесттің орташа ұпайы 12. Алғашқы екеуі 10 және 14. Үшінші ұпай қандай?","answer":"12","steps":["Үш тест қосындысы 36.","36 − 10 − 14 = 12."]}]},{"id":"data-06","title":"Медиана","rule":"Медиана — реттелген қатардың ортасындағы мән; саны жұп болса, ортасындағы екеудің орташасы.","trap":"Медиана әрқашан ең жиі кездесетін сан.","problems":[{"q":"3, 11, 7, 5, 9 қатарының медианасын тап.","answer":"7","steps":["Реттелген қатар: 3, 5, 7, 9, 11.","ортасы 7."]},{"q":"2, 4, 8, 10 қатарының медианасын тап.","answer":"6","steps":["Ортадағы мәндер 4 және 8.","(4 + 8) / 2 = 6."]}]},{"id":"data-07","title":"Мода","rule":"Мода — деректерде ең жиі кездесетін мән.","trap":"Мода міндетті түрде ең үлкен сан болады.","problems":[{"q":"2, 4, 4, 5, 7, 4 сандарының модасын тап.","answer":"4","steps":["4 саны үш рет кездеседі.","қалғандары бір реттен."]},{"q":"6, 8, 6, 9, 8, 8, 10 қатарының модасын тап.","answer":"8","steps":["8 саны үш рет кездеседі.","ол ең жиі мән."]}]},{"id":"data-08","title":"Өзгеріс ауқымы","rule":"Өзгеріс ауқымы ең үлкен және ең кіші мәннің айырмасына тең.","trap":"Өзгеріс ауқымы ең үлкен және ең кіші мәннің қосындысы.","problems":[{"q":"12, 19, 7, 15 сандарының өзгеріс ауқымын тап.","answer":"12","steps":["Ең үлкені 19, ең кішісі 7.","ауқымы 12."]},{"q":"Апталық температуралар: −3, 2, 5, −1, 4°C. Ауқымы қанша?","answer":"8","steps":["Максимум 5, минимум −3.","5 − (−3) = 8°C."]}]},{"id":"data-09","title":"Мәліметтерді салыстыру","rule":"Салыстыру үшін абсолют айырманы немесе бастапқы мәнге қатысты пайызды есептеуге болады.","trap":"Пайыздық өсім есептелгенде бөлімге әрқашан жаңа мән жазылады.","problems":[{"q":"A сыныбы 48, B сыныбы 60 ағаш отырғызды. B сыныбы қанша пайыз артық отырғызды?","answer":"25","steps":["Айырма 12.","12 / 48 × 100% = 25%."]},{"q":"Өткен айда 80, осы айда 100 кітап оқылды. Өсім неше кітап?","answer":"20","steps":["Абсолют өсім 100 − 80 = 20.","оны пайызбен шатастырма."]}]},{"id":"data-10","title":"Графиктен қажетті мәнді табу","rule":"Графиктен мән алу үшін қажетті x нүктесінен графикке, одан y осіне өтеміз.","trap":"Графиктің екі осін орындарын ауыстырып оқу нәтижеге әсер етпейді.","problems":[{"q":"График нүктелері: (1; 4), (2; 7), (3; 10). x = 2 кезіндегі y-ті тап.","answer":"7","steps":["x = 2 нүктесіне сәйкес жұп — (2.","7).","y = 7."]},{"q":"График нүктелері: (0; 3), (1; 5), (2; 7). x = 3 болса, осы сызықтық заңдылықтағы y қандай?","answer":"9","steps":["x бір бірлікке артқанда y екіге өседі.","7 + 2 = 9."]}]},{"id":"data-11","title":"Диаграммадағы пайыздарды есептеу","rule":"Диаграммадағы бөлік пайызы бөлікті жалпы мәнге бөліп анықталады.","trap":"20 адамның 5-еуі барлықтың 20%-ы.","problems":[{"q":"80 оқушының 24-і футболды таңдады. Бұл неше пайыз?","answer":"30","steps":["24 / 80 = 0,3.","пайызбен 30%."]},{"q":"Бюджет диаграммасында 150 000 ₸-дің 45 000 ₸-і азыққа тиесілі. Үлесі неше пайыз?","answer":"30","steps":["45 000 / 150 000 = 0,3.","бұл 30%."]}]}],"number":9},{"id":"probability","title":"Ықтималдық","color":"#d3b0ea","symbol":"⚄","lessons":[{"id":"probability-01","title":"Кездейсоқ оқиғалар","rule":"Кездейсоқ оқиға болуы да, болмауы да мүмкін; ақиқат оқиға міндетті түрде орындалады.","trap":"Кездейсоқ оқиға әрқашан орындалады.","problems":[{"q":"Кәдімгі сүйекте 1-ден 6-ға дейінгі сан түсу ықтималдығын жаз.","answer":"1","steps":["Барлық 6 нәтиже қолайлы.","P = 6/6 = 1."]},{"q":"Кәдімгі сүйекте 9 саны түсу ықтималдығын жаз.","answer":"0","steps":["9 деген нәтиже жоқ.","мүмкін емес оқиғаның ықтималдығы 0."]}]},{"id":"probability-02","title":"Оқиғаның ықтималдығы","rule":"Тең ықтималды жағдайларда P = қолайлы жағдайлар саны / барлық жағдайлар саны.","trap":"Ықтималдық 1-ден үлкен болуы мүмкін.","problems":[{"q":"10 карточканың 4-еуі ұтысты. Ұтыс ықтималдығын ондық бөлшекпен жаз.","answer":"0.4","steps":["Қолайлы 4, барлық 10.","P = 4/10 = 0,4."]},{"q":"8 билеттің 2-еуі жеңімпаз. Ұтыс ықтималдығын пайызбен жаз.","answer":"25","steps":["P = 2/8 = 0,25.","бұл 25%."]}]},{"id":"probability-03","title":"Қолайлы жағдайлар саны","rule":"Қолайлы жағдайлар — есептегі талапты орындайтын нәтижелер.","trap":"Қолайлы жағдайлар саны барлық жағдайлар санынан үлкен болуы мүмкін.","problems":[{"q":"1-ден 12-ге дейінгі карточкалардың нешеуі 4-ке бөлінеді?","answer":"3","steps":["Карточкалар: 4, 8, 12.","қолайлы жағдай саны 3."]},{"q":"Сүйек лақтырғанда 4-тен үлкен неше нәтиже болуы мүмкін?","answer":"2","steps":["Қолайлы нәтижелер — 5 және 6.","олардың саны 2."]}]},{"id":"probability-04","title":"Барлық мүмкін жағдайлар саны","rule":"Барлық мүмкін жағдайларды толық әрі қайталамай санау керек.","trap":"Екі сүйек лақтырғанда барлық реттелген нәтиже саны 12.","problems":[{"q":"Екі рет тиын лақтырғанда неше реттелген нәтиже болады?","answer":"4","steps":["Нәтижелер: ЕЕ, ЕС, СЕ, СС.","барлығы 4."]},{"q":"Бір сүйек пен бір тиын лақтырғанда барлық реттелген нәтиже саны қанша?","answer":"12","steps":["6 сүйек нәтижесі × 2 тиын нәтижесі.","барлығы 12."]}]},{"id":"probability-05","title":"Монета лақтыру","rule":"Әділ тиынның екі беті тең ықтималды болады.","trap":"Әділ тиынның елтаңба түсу ықтималдығы 1.","problems":[{"q":"Тиын бір рет лақтырылғанда елтаңба түсу ықтималдығын ондық бөлшекпен жаз.","answer":"0.5","steps":["Екі тең мүмкіндік бар.","P = 1/2 = 0,5."]},{"q":"Тиын екі рет лақтырылғанда екі рет те елтаңба түсу ықтималдығын жаз.","answer":"0.25","steps":["Барлық нәтиже саны 4.","қолайлысы ЕЕ, сондықтан 1/4 = 0,25."]}]},{"id":"probability-06","title":"Ойын сүйегін лақтыру","rule":"Әділ сүйектегі 1–6 сандары тең ықтималды болады.","trap":"Сүйекте 6 саны түсу ықтималдығы 1/2.","problems":[{"q":"Сүйектегі жұп сан түсу ықтималдығын ондық бөлшекпен жаз.","answer":"0.5","steps":["Жұп нәтижелер 2, 4, 6.","P = 3/6 = 0,5."]},{"q":"Сүйекте 5-тен кіші сан түсу ықтималдығын пайызбен жаз. Ондық үлеске дейін дөңгелекте.","answer":"66.7","steps":["Қолайлы 1, 2, 3, 4.","4/6 × 100% ≈ 66,7%."]}]},{"id":"probability-07","title":"Қораптан зат таңдау","rule":"Қораптан кездейсоқ зат алғанда әр затты тең ықтималды деп алу шарты маңызды.","trap":"Ақаулы зат ықтималдығы мен жарамды зат ықтималдығының қосындысы 0.","problems":[{"q":"Қорапта 6 ақ, 4 қара қалам бар. Ақ қалам ықтималдығын жаз.","answer":"0.6","steps":["Барлығы 10 қалам.","P = 6/10 = 0,6."]},{"q":"Қорапта 12 заттың 3-еуі ақаулы. Жарамды зат алу ықтималдығын жаз.","answer":"0.75","steps":["Жарамды 12 − 3 = 9.","P = 9/12 = 0,75."]}]},{"id":"probability-08","title":"Түрлі түсті шарлар","rule":"Түрлі түсті шарлар үшін барлық шар саны бөлімге жазылады.","trap":"Қызыл шар ықтималдығын есептегенде бөлімге тек көк шар санын жазамыз.","problems":[{"q":"5 қызыл, 3 көк, 2 жасыл шар бар. Көк шар ықтималдығын жаз.","answer":"0.3","steps":["Барлық шар саны 10.","көк шар саны 3.","P = 0,3."]},{"q":"8 шардың 6-уы қызыл. Қызыл емес шар ықтималдығын жаз.","answer":"0.25","steps":["Қызыл емес шар 2.","P = 2/8 = 0,25."]}]},{"id":"probability-09","title":"Карточкалар мен сандар","rule":"Сандық карточкада қажетті қасиетті қанағаттандыратын сандарды санаймыз.","trap":"1 — жай сан, сондықтан оны жай карточкаларға қосамыз.","problems":[{"q":"1–20 карточкадан біреу алынды. 5-ке еселі сан ықтималдығын жаз.","answer":"0.2","steps":["Қолайлы сандар: 5, 10, 15, 20.","4/20 = 0,2."]},{"q":"1–10 карточкадан жай сан түсу ықтималдығын жаз.","answer":"0.4","steps":["Жай сандар: 2, 3, 5, 7.","4/10 = 0,4."]}]},{"id":"probability-10","title":"Қарапайым ықтималдық есептері","rule":"Қарама-қарсы оқиғалардың ықтималдықтары қосылып 1 болады.","trap":"Оқиға мен оған қарама-қарсы оқиғаның ықтималдықтары әрқашан тең.","problems":[{"q":"Жаңбыр жауу ықтималдығы 0,35. Жаңбыр жаумау ықтималдығын тап.","answer":"0.65","steps":["Қарама-қарсы оқиға: 1 − 0,35 = 0,65."]},{"q":"20 бірдей мүмкіндік ішінде 7 қолайлы болса, қолайсыз оқиға ықтималдығын тап.","answer":"0.65","steps":["Қолайсыз саны 13.","P = 13/20 = 0,65."]}]}],"number":10},{"id":"logic","title":"Логикалық есептер","color":"#efc48b","symbol":"∞","lessons":[{"id":"logic-01","title":"Сандық тізбектер","rule":"Сандық тізбектің ережесі барлық берілген ауысуға сәйкес болуы керек.","trap":"Қатардағы алғашқы айырма барлық тізбек үшін міндетті түрде тұрақты.","problems":[{"q":"4, 9, 14, 19, … тізбегінің келесі санын тап.","answer":"24","steps":["Айырма тұрақты: +5.","келесі сан 24."]},{"q":"2, 6, 18, 54, … тізбегін жалғастыр.","answer":"162","steps":["Әр мүше 3-ке көбейеді.","54 × 3 = 162."]}]},{"id":"logic-02","title":"Фигуралар тізбегі","rule":"Фигуралар тізбегінде пішін, түс, бұрылыс не элемент саны қайталануы мүмкін.","trap":"Үш мүшелік циклдің 6-мүшесі міндетті түрде 1-мүшеге тең.","problems":[{"q":"△, □, ○, △, □, ○, … қатарында 10-орында қай пішін? △ = 1, □ = 2, ○ = 3 деп жауап бер.","answer":"1","steps":["Үш пішіндік цикл бар.","10-ды 3-ке бөлгенде қалдық 1, демек △."]},{"q":"Бірінші фигурада 3, екіншісінде 5, үшіншісінде 7 нүкте бар. Осы ереже бойынша 8-фигурада неше нүкте?","answer":"17","steps":["Әр фигурада 2 нүкте қосылады.","3 + 7 × 2 = 17."]}]},{"id":"logic-03","title":"Заңдылықты табу","rule":"Заңдылықта екі не одан көп ереже кезектесіп жүруі мүмкін.","trap":"Кез келген тізбекте тек бірдей қосу амалы қолданылады.","problems":[{"q":"1, 4, 2, 8, 3, 12, 4, … қатарындағы келесі санды тап.","answer":"16","steps":["Жұптар: (1;4), (2;8), (3;12), (4;16).","екінші сан біріншіден 4 есе үлкен."]},{"q":"5, 10, 8, 16, 14, … қатарын жалғастыр.","answer":"28","steps":["Амалдар кезектеседі: ×2, −2.","14-тен кейін ×2, яғни 28."]}]},{"id":"logic-04","title":"Артық элементті анықтау","rule":"Артық элементті табу үшін ортақ қасиетті нақты анықтау керек.","trap":"Артық элементті ешбір ережесіз таңдауға болады.","problems":[{"q":"2, 3, 5, 9, 11 қатарындағы жалғыз құрама санды тап.","answer":"9","steps":["2, 3, 5, 11 — жай.","9 = 3 × 3, ол құрама."]},{"q":"16, 25, 36, 48, 49 қатарындағы толық квадрат емес санды тап.","answer":"48","steps":["Қалғандары 4², 5², 6², 7².","48 толық квадрат емес."]}]},{"id":"logic-05","title":"Логикалық кестелер","rule":"Логикалық кестеде әр шартқа сәйкес келмейтін мүмкіндіктерді біртіндеп алып тастаймыз.","trap":"Логикалық кестеде бір шартты сақтап, қалғанын елемеуге болады.","problems":[{"q":"A, B, C әртүрлі 1, 2, 3 орын алды. A бірінші емес, C үшінші емес, B бірінші. C нешінші?","answer":"2","steps":["B — 1.","C үшінші емес болғандықтан 2.","A — 3."]},{"q":"Үш балада алма, алмұрт, банан бар. Әлиде банан емес, Данада алма бар, Әлиде алма жоқ. Банан кімде? Әли = 1, Дана = 2, Мира = 3.","answer":"3","steps":["Әлиде алмұрт, Данада алма.","қалған банан Мирада, жауап 3."]}]},{"id":"logic-06","title":"Ақиқат және жалған пікірлер","rule":"Ақиқат пікір шындыққа сәйкес келеді; пікірдің терістеуі оның мәнін өзгертеді.","trap":"Жалған пікірді терістесек, қайтадан жалған пікір аламыз.","problems":[{"q":"3 > 1; 5 жұп; 7 жай; 0 < −1 пікірлерінің нешеуі ақиқат?","answer":"2","steps":["Бірінші және үшінші пікір ақиқат.","қалғандары жалған."]},{"q":"«Барлық төртбұрыш — шаршы» және «Әр шаршы — төртбұрыш» пікірлерінің нешеуі ақиқат?","answer":"1","steps":["Бірінші пікір жалған.","екінші пікір ақиқат."]}]},{"id":"logic-07","title":"Жасқа байланысты есептер","rule":"Жас айырмасы жылдар өткенде өзгермейді.","trap":"Екі адамның жас қатынасы жылдар өткенде әрқашан тұрақты болады.","problems":[{"q":"Әкесі 36, баласы 12 жаста. Неше жылдан кейін әкесі баласынан 2 есе үлкен болады?","answer":"12","steps":["36 + x = 2(12 + x).","x = 12 жыл."]},{"q":"Екі баланың жас қосындысы 25, айырмасы 5. Кішісі неше жаста?","answer":"10","steps":["x + x + 5 = 25.","x = 10."]}]},{"id":"logic-08","title":"Күнтізбе және апта күндері","rule":"Апта күндері 7 күн сайын қайталанады; күн санын 7-ге бөлгендегі қалдық маңызды.","trap":"Кез келген жылда ақпан 29 күннен тұрады.","problems":[{"q":"Бүгін дүйсенбі. 100 күннен кейінгі күнді дүйсенбі = 1, …, жексенбі = 7 деп жаз.","answer":"3","steps":["100 күннің 7-ге қалдығы 2.","дүйсенбіден екі күн кейін — сәрсенбі, яғни 3."]},{"q":"Қарапайым жылда ақпан неше күннен тұрады?","answer":"28","steps":["Қарапайым жылда ақпан 28 күн.","кібісе жылда 29 күн болады."]}]},{"id":"logic-09","title":"Сағат тіліне байланысты есептер","rule":"Минут тілі минутына 6°, сағат тілі минутына 0,5° қозғалады.","trap":"6:30 кезінде сағат тілі дәл 6 санының үстінде тұрады.","problems":[{"q":"Сағат 3:00 болғанда тілдер арасындағы кіші бұрыш неше градус?","answer":"90","steps":["Сағат тілі 3-те, минут тілі 12-де.","аралық 3 × 30° = 90°."]},{"q":"Сағат 6:30 болғанда тілдер арасындағы кіші бұрыш неше градус?","answer":"15","steps":["Минут тілі 180°-та.","сағат тілі 195°-та, айырмасы 15°."]}]},{"id":"logic-10","title":"Орындарды анықтау","rule":"Екі жақтан берілген орындар бойынша жалпы санды n = сол жақ орын + оң жақ орын − 1 арқылы табамыз.","trap":"Екі жақтан орындарды қоссақ, ортадағы адам ешқашан қайталанбайды.","problems":[{"q":"Әли сол жақтан 7-ші, оң жақтан 9-шы. Қатарда неше адам бар?","answer":"15","steps":["Әли екі рет саналды.","7 + 9 − 1 = 15."]},{"q":"20 адамдық қатарда Дана сол жақтан 6-шы. Оң жақтан нешінші?","answer":"15","steps":["Оң жақ орын: 20 − 6 + 1 = 15."]}]},{"id":"logic-11","title":"Реттілікті табу","rule":"Реттілікті анықтағанда алдындағы және кейінгі шарттарды бір тізбекке келтіреміз.","trap":"«A B-дан бұрын» шарты A міндетті түрде бірінші дегенді білдіреді.","problems":[{"q":"A — B-дан бұрын, C — B-дан кейін, D — C-дан кейін. D нешінші?","answer":"4","steps":["Рет: A, B, C, D.","D төртінші."]},{"q":"Бес оқушыда A — үшінші, B — A-дан екі орын кейін. B нешінші?","answer":"5","steps":["B орны: 3 + 2 = 5.","қатар шартына сәйкес."]}]},{"id":"logic-12","title":"Қол алысу есептері","rule":"Әр адам бір-бірімен бір рет қол алысса, жұп саны n(n−1)/2 болады.","trap":"7 адамның қол алысу саны 7 × 6 = 42.","problems":[{"q":"7 адам бір-бірімен бір рет қол алысты. Барлығы неше қол алысу?","answer":"21","steps":["7 × 6 = 42.","әр жұп екі рет саналған, 42 / 2 = 21."]},{"q":"10 команда бір-бірімен бір рет ойнады. Барлығы неше ойын?","answer":"45","steps":["Жұптар саны 10 × 9 / 2.","барлығы 45 ойын."]}]},{"id":"logic-13","title":"Ең үлкен және ең кіші мәнді табу","rule":"Ең үлкен не кіші мәнді табуда барлық шектеу бір уақытта орындалуы керек.","trap":"Ең кіші үш таңбалы санды 0 цифрынан бастауға болады.","problems":[{"q":"Қайталанбайтын 2, 5, 7 цифрларынан ең үлкен үш таңбалы санды құрастыр.","answer":"752","steps":["Ең үлкен цифр жүздікке қойылады.","7, 5, 2 → 752."]},{"q":"Цифрлары әртүрлі ең кіші үш таңбалы санды жаз.","answer":"102","steps":["Жүздік 1.","ондық 0.","ең кіші қалған цифр 2, сан 102."]}]}],"number":11},{"id":"combinatorics","title":"Комбинаторика және санау","color":"#b1cff2","symbol":"n!","lessons":[{"id":"combinatorics-01","title":"Қосу ережесі","rule":"Бірін-бірі жоққа шығаратын таңдаулардың жалпы саны қосу ережесімен табылады.","trap":"Баламалы бір ғана таңдау үшін нұсқалар санын әрқашан көбейтеміз.","problems":[{"q":"4 түрлі шайдың немесе 3 түрлі шырынның бірін таңдайсың. Неше таңдау бар?","answer":"7","steps":["Бір ғана сусын алынады.","4 + 3 = 7 нұсқа."]},{"q":"A сөресінде 8, B сөресінде басқа 5 кітап бар. Бір кітапты неше тәсілмен таңдауға болады?","answer":"13","steps":["Екі сөредегі кітаптар бөлек.","8 + 5 = 13."]}]},{"id":"combinatorics-02","title":"Көбейту ережесі","rule":"Кезеңдер бірінен кейін бірі таңдалса, нұсқалар саны көбейтіледі.","trap":"3 жейде және 4 шалбардан толық жұп саны 7.","problems":[{"q":"3 жейде мен 4 шалбардан неше киім жұбы құралады?","answer":"12","steps":["Әр жейдеге 4 шалбар.","3 × 4 = 12 жұп."]},{"q":"2 сорпа, 3 негізгі ас, 2 сусыннан әрқайсысының біреуін алу тәсілі нешеу?","answer":"12","steps":["Үш таңдау кезеңі бар.","2 × 3 × 2 = 12."]}]},{"id":"combinatorics-03","title":"Нұсқаларды санау","rule":"Нұсқаларды ағаш, кесте немесе толық тізім арқылы қайталамай санауға болады.","trap":"Рет маңызды есепте 12 мен 21 бірдей нұсқа болып саналады.","problems":[{"q":"Екі әртүрлі тиынды лақтырғанда неше реттелген нәтиже бар?","answer":"4","steps":["ЕЕ, ЕС, СЕ, СС.","барлығы 4 реттелген нәтиже."]},{"q":"1, 2, 3 цифрларынан қайталамай неше екі таңбалы сан құралады?","answer":"6","steps":["Бірінші орынға 3, екіншіге 2 таңдау.","3 × 2 = 6."]}]},{"id":"combinatorics-04","title":"Орналастырудың қарапайым түрлері","rule":"Орналастыруда таңдау реті маңызды болады.","trap":"Төраға мен орынбасардың орнын ауыстыру жаңа нәтиже бермейді.","problems":[{"q":"5 адамның ішінен төраға мен орынбасарды неше тәсілмен таңдауға болады?","answer":"20","steps":["Төрағаға 5, орынбасарға 4 таңдау.","5 × 4 = 20."]},{"q":"4 түрлі кітапты сөреге неше ретпен орналастыруға болады?","answer":"24","steps":["Реттер саны 4 × 3 × 2 × 1 = 24."]}]},{"id":"combinatorics-05","title":"Комбинациялар","rule":"Комбинацияда таңдалған топтың реті маңызды емес.","trap":"Екі адамдық топта A мен B таңдауы B мен A таңдауынан бөлек.","problems":[{"q":"5 оқушыдан екі адамдық топты неше тәсілмен таңдаймыз?","answer":"10","steps":["Реттелген жұп саны 5 × 4 = 20.","2-ге бөлсек, 10 топ."]},{"q":"6 түрлі кітаптың ішінен 2 кітапты неше тәсілмен таңдаймыз?","answer":"15","steps":["6 × 5 / 2 = 15.","кітап алу реті есептелмейді."]}]},{"id":"combinatorics-06","title":"Құпиясөздер мен кодтар","rule":"Құпиясөздегі әр орынға рұқсат етілген таңбалар саны мен қайталану шартын ескереміз.","trap":"Кодтағы әр цифр 10 нұсқалы болса, үш орын үшін барлығы 30 код.","problems":[{"q":"Әр орнына 0–9 цифрлары қайталанып келе алатын үш цифрлы код нешеу?","answer":"1000","steps":["Әр орынға 10 мүмкіндік.","10³ = 1 000 код."]},{"q":"A, B, C, D әріптерінен қайталамай екі әріптік код нешеу?","answer":"12","steps":["Бірінші орынға 4, екіншісіне 3.","4 × 3 = 12."]}]},{"id":"combinatorics-07","title":"Цифрлардан сандар құрастыру","rule":"Көп таңбалы санның бірінші цифры нөл бола алмайды.","trap":"012 — үш таңбалы сан.","problems":[{"q":"0, 1, 2 цифрларынан қайталамай неше екі таңбалы сан құралады?","answer":"4","steps":["Біріншіге 1 не 2.","әрқайсысына 2 екінші цифр, барлығы 4."]},{"q":"1, 2, 3, 4 цифрларынан қайталамай неше үш таңбалы сан құралады?","answer":"24","steps":["4 × 3 × 2 = 24.","бірінші цифрға нөл шектеуі жоқ."]}]},{"id":"combinatorics-08","title":"Қайталанатын және қайталанбайтын таңдау","rule":"Қайталауға рұқсат болса таңдау саны азаймайды; рұқсат болмаса әр қадамда кемиді.","trap":"Қайталауға рұқсат беру нұсқалар санын міндетті түрде азайтады.","problems":[{"q":"5 таңбадан қайталауға рұқсат етіп екі таңбалы код құру тәсілі нешеу?","answer":"25","steps":["Бірінші және екінші орынға 5-тен.","5 × 5 = 25."]},{"q":"Сол 5 таңбадан қайталамай екі таңбалы код құру тәсілі нешеу?","answer":"20","steps":["Бірінші орынға 5, екіншісіне 4.","5 × 4 = 20."]}]}],"number":12},{"id":"sets","title":"Жиындар","color":"#8ee0ce","symbol":"∩","lessons":[{"id":"sets-01","title":"Жиын ұғымы","rule":"Жиынның элементтері қайталанбай есептеледі.","trap":"Бір жиын ішінде бір элемент екі рет жеке элемент ретінде саналады.","problems":[{"q":"A = {1, 2, 2, 3, 3, 4} жиынында неше әртүрлі элемент бар?","answer":"4","steps":["Қайталануды алып таста: {1, 2, 3, 4}.","қуаты 4."]},{"q":"10-нан кіші оң жұп бүтін сандар жиынының элемент санын тап.","answer":"4","steps":["Элементтер: 2, 4, 6, 8.","барлығы 4."]}]},{"id":"sets-02","title":"Жиындардың бірігуі","rule":"Бірігу екі жиынның кем дегенде біреуіне кіретін барлық элементті қамтиды.","trap":"Бірігу элементтер саны әрқашан жеке қуаттар қосындысына тең.","problems":[{"q":"A = {1,2,3}, B = {3,4,5}. Бірігудің элемент саны қанша?","answer":"5","steps":["Бірігу {1,2,3,4,5}.","ортақ 3 бір рет есептеледі."]},{"q":"A-да 12, B-да 10 элемент, ортағы 4. Бірігудің қуаты қанша?","answer":"18","steps":["12 + 10 − 4 = 18.","ортақ элементтерді екі рет есептемейміз."]}]},{"id":"sets-03","title":"Жиындардың қиылысуы","rule":"Қиылысу екі жиынға да бірдей кіретін элементтерден тұрады.","trap":"Қиылысуға тек бір ғана жиында бар элементтер кіреді.","problems":[{"q":"A = {2,4,6,8}, B = {1,2,3,4}. Ортақ элементтер саны қанша?","answer":"2","steps":["Ортақ элементтер 2 және 4.","қуаты 2."]},{"q":"15 оқушы футболға, 12-сі шахматқа қатысады, кемінде біреуіне 20 оқушы қатысады. Екеуіне де нешеуі қатысады?","answer":"7","steps":["Қиылысу: 15 + 12 − 20 = 7."]}]},{"id":"sets-04","title":"Эйлер–Венн диаграммалары","rule":"Венн диаграммасында ортақ бөлік қиылысуды, екі дөңгелек бірігіп бірігуді көрсетеді.","trap":"Венн диаграммасының екі дөңгелегі қабысқан бөлігі бірігуге кірмейді.","problems":[{"q":"A жиыны 18, B жиыны 14, ортақ бөлігі 6. Тек A-да неше элемент?","answer":"12","steps":["Тек A: 18 − 6 = 12.","ортақ бөлік A санына кіріп тұр."]},{"q":"Барлығы 40 оқушы, екі үйірменің бірігуі 32. Екеуіне де қатыспайтыны нешеу?","answer":"8","steps":["Дөңгелектер сыртындағы бөлік: 40 − 32 = 8."]}]},{"id":"sets-05","title":"Екі жиынға қатысты есептер","rule":"Екі жиын үшін қосу-алу формуласы: n(A∪B) = n(A) + n(B) − n(A∩B).","trap":"Екі жиын есебінде ортақ бөлікті екі рет қосу қажет.","problems":[{"q":"30 оқушының 17-сі жүзеді, 15-і жүгіреді, 8-і екеуін де істейді. Ешқайсысын істемейтіні нешеу?","answer":"6","steps":["Бірігу 17 + 15 − 8 = 24.","сыртында 30 − 24 = 6."]},{"q":"25 оқушының 16-сы кітап, 14-і комикс оқиды, барлығы кемінде біреуін оқиды. Екеуін де оқитыны қанша?","answer":"5","steps":["16 + 14 − 25 = 5.","ортақ оқушылар саны 5."]}]},{"id":"sets-06","title":"Үш жиынға қатысты есептер","rule":"Үш жиын бірігуінде жеке қуаттарды қосып, жұп қиылысуларды алып, үштік қиылысуды қайта қосамыз.","trap":"Үш жиынның бірігу формуласына үштік қиылысуды ешқашан қоспаймыз.","problems":[{"q":"n(A)=10, n(B)=12, n(C)=8, жұп қиылысулар 3,2,4, үштік қиылысу 1. Бірігу қуаты қанша?","answer":"22","steps":["10 + 12 + 8 − 3 − 2 − 4 + 1 = 22."]},{"q":"Үш үйірмеде 15, 14, 13 оқушы бар, әр жұп қиылысуы 5, үшеуінде де 2 оқушы. Кемінде біреуіне нешеуі қатысады?","answer":"29","steps":["15 + 14 + 13 − 5 − 5 − 5 + 2 = 29."]}]},{"id":"sets-07","title":"Ортақ элементтерді санау","rule":"Ортақ элементтер санауда артық қайталануды түзетеді.","trap":"2-ге де, 3-ке де бөлінетін сан міндетті түрде 5-ке бөлінеді.","problems":[{"q":"1–30 сандарының ішінде 2-ге де, 3-ке де бөлінетін неше сан бар?","answer":"5","steps":["Екі шартқа да сай сандар 6-ға бөлінеді.","6,12,18,24,30 — бесеу."]},{"q":"1–20 ішінде 2-ге немесе 5-ке бөлінетін сандар нешеу?","answer":"12","steps":["Жұптар 10, 5 еселіктері 4, ортағы 2.","10 + 4 − 2 = 12."]}]}],"number":13},{"id":"mixtures","title":"Қоспалар және концентрация","color":"#eeb6d2","symbol":"◉","lessons":[{"id":"mixtures-01","title":"Қоспадағы заттың пайыздық үлесі","rule":"Қоспадағы заттың үлесі таза зат массасының қоспа массасына қатынасына тең.","trap":"Қоспадағы үлесті табу үшін таза зат массасын қалған қоспа массасына бөлеміз.","problems":[{"q":"200 г қоспада 30 г тұз бар. Тұз үлесі неше пайыз?","answer":"15","steps":["30 / 200 × 100% = 15%.","бөлімде барлық қоспа массасы."]},{"q":"500 г қорытпаның 40%-ы мыс. Мыс массасы неше грамм?","answer":"200","steps":["500 × 0,4 = 200 г.","қалған бөлігі 300 г."]}]},{"id":"mixtures-02","title":"Ерітінді концентрациясы","rule":"Концентрация таза еріген зат массасын ерітіндінің толық массасымен салыстырады.","trap":"20 г тұзды 80 г суға қоссақ, концентрация 25% болады.","problems":[{"q":"300 г 12% ерітіндіде неше грамм тұз бар?","answer":"36","steps":["Таза зат: 300 × 0,12 = 36 г."]},{"q":"20 г тұз 80 г суда ерітілді. Ерітінді концентрациясы неше пайыз?","answer":"20","steps":["Ерітінді массасы 20 + 80 = 100 г.","үлесі 20/100 = 20%."]}]},{"id":"mixtures-03","title":"Әртүрлі қоспаларды араластыру","rule":"Қоспаларды араластырғанда таза зат массалары да, толық массалар да қосылады.","trap":"Массалары әртүрлі қоспалардың концентрацияларын әрқашан жай орташа мәнмен табамыз.","problems":[{"q":"100 г 10% және 100 г 30% тұз ерітінділері араласты. Жаңа концентрация неше пайыз?","answer":"20","steps":["Тұз 10 + 30 = 40 г.","ерітінді 200 г.","40/200 = 20%."]},{"q":"200 г 10% және 100 г 40% ерітінді араласты. Концентрация неше пайыз?","answer":"20","steps":["Таза зат 20 + 40 = 60 г.","жалпы 300 г.","концентрация 20%."]}]},{"id":"mixtures-04","title":"Су қосу","rule":"Таза су қосылғанда тұз массасы сақталады, ерітінді массасы өседі.","trap":"Таза су қосылса, тұз массасы да сол мөлшерде өседі.","problems":[{"q":"200 г 20% ерітіндіге 200 г су қосылды. Концентрация қанша пайыз?","answer":"10","steps":["Тұз 40 г болып қалды.","ерітінді 400 г.","40/400 = 10%."]},{"q":"100 г 30% ерітіндіні 10%-ға дейін сұйылту үшін неше г су қосу керек?","answer":"200","steps":["Тұз 30 г.","толық масса 30/0,1 = 300 г.","қосылатын су 200 г."]}]},{"id":"mixtures-05","title":"Булану","rule":"Тек су буланғанда еріген тұз массасы өзгермейді, концентрация артады.","trap":"Тек су буланғанда тұз концентрациясы кемиді.","problems":[{"q":"500 г 10% ерітіндіден 250 г су буланды. Жаңа концентрация неше пайыз?","answer":"20","steps":["Тұз 50 г.","жаңа толық масса 250 г.","50/250 = 20%."]},{"q":"200 г 15% ерітіндіні 30%-ға жеткізу үшін неше г су буландыру керек?","answer":"100","steps":["Тұз 30 г.","қажетті масса 30/0,3 = 100 г.","буланатыны 100 г."]}]},{"id":"mixtures-06","title":"Құрамындағы таза зат мөлшерін табу","rule":"Таза зат массасы толық масса мен пайыздық үлестің көбейтіндісіне тең.","trap":"Таза зат массасын табу үшін қоспа массасын пайыздық үлеске бөлеміз.","problems":[{"q":"1,5 кг 8% қоспадағы таза зат неше грамм?","answer":"120","steps":["1,5 кг = 1 500 г.","1 500 × 0,08 = 120 г."]},{"q":"24 г қант 12% ерітіндіде бар. Толық ерітінді неше грамм?","answer":"200","steps":["Толық масса 24 / 0,12 = 200 г."]}]}],"number":14},{"id":"practical","title":"Практикалық мәтіндік есептер","color":"#a9d49b","symbol":"⌁","lessons":[{"id":"practical-01","title":"Отбасылық шығындар","rule":"Тұрмыстық шығынды жоспарлау үшін әр санаттағы сомаларды қосып, кіріспен салыстырамыз.","trap":"Бюджетті есептегенде ұсақ күнделікті шығындарды елемеуге болады.","problems":[{"q":"240 000 ₸ кірістен азыққа 70 000, үйге 50 000, жолға 20 000 ₸ кетті. Қалғаны қанша?","answer":"100000","steps":["Шығыс 140 000.","240 000 − 140 000 = 100 000 ₸."]},{"q":"Күніне 1 200 ₸ жол мен асқа жұмсалса, 22 жұмыс күніндегі шығын қанша?","answer":"26400","steps":["Бір күндік шығынды күн санына көбейт.","1 200 × 22 = 26 400 ₸."]}]},{"id":"practical-02","title":"Билет пен жолақы","rule":"Билет құнында жолаушы санын, жеңілдікті және әр санаттың бағасын есептейміз.","trap":"50% балалар жеңілдігі бар билет тегін болады.","problems":[{"q":"Ересек билеті 2 000 ₸, балаға 50% жеңілдік. Екі ересек пен үш балаға қанша төленеді?","answer":"7000","steps":["Ересектер 4 000.","балалар 3 × 1 000 = 3 000.","барлығы 7 000 ₸."]},{"q":"Бір сапар 150 ₸, айлық жолақы 5 000 ₸. 40 сапарға жолақы алса, неше теңге үнемдейді?","answer":"1000","steps":["Жеке төлем 40 × 150 = 6 000.","үнем 1 000 ₸."]}]},{"id":"practical-03","title":"Автобус және пойыз кестесі","rule":"Кесте есебінде келу мен кету уақытын, аялдау мен күн ауысуын ескереміз.","trap":"Түн ортасынан өткен сапар уақытын сағаттарды жай азайту арқылы әрқашан табамыз.","problems":[{"q":"Автобус 08:35-те шығып, 10:10-да келді. Жол неше минутқа созылды?","answer":"95","steps":["08:35-тен 09:35-ке 60 минут.","тағы 35 минут, барлығы 95."]},{"q":"Пойыз 23:20-да шығып, келесі күні 01:05-те келді. Жол неше минут?","answer":"105","steps":["Түн ортасына 40 минут.","кейін 65 минут.","барлығы 105."]}]},{"id":"practical-04","title":"Туристік маршрут","rule":"Маршрут есебінде жол бөліктерін және аялдау уақыттарын бөлек қосамыз.","trap":"Аялдау уақыты сапардың жалпы уақытына кірмейді.","problems":[{"q":"Турист 12 км жаяу, 28 км автобуспен, 10 км велосипедпен жүрді. Жалпы жол неше км?","answer":"50","steps":["Жол бөліктері қосылады.","12 + 28 + 10 = 50 км."]},{"q":"60 км маршрут 30 км/сағ жылдамдықпен өтіліп, 30 минут аялдады. Жалпы уақыт неше минут?","answer":"150","steps":["Қозғалыс 2 сағат = 120 минут.","аялдаумен бірге 150 минут."]}]},{"id":"practical-05","title":"Жанармай шығыны","rule":"Жанармай бюджетін есептеу үшін жүріс нормасын, қашықтықты және литр бағасын байланыстырамыз.","trap":"Жанармайдың литрлік шығыны мен оның теңгелік құны бір шама.","problems":[{"q":"240 км жол, 100 км-ге 7,5 л. Қажет жанармай неше литр?","answer":"18","steps":["240 / 100 × 7,5.","нәтиже 18 л."]},{"q":"400 км-ге 32 л жұмсалды. 100 км-ге шығын неше литр?","answer":"8","steps":["32 / 400 × 100 = 8 л/100 км."]}]},{"id":"practical-06","title":"Өнімділік және егін жинау","rule":"Егін өнімділігі жалпы өнімнің егістік ауданына қатынасы арқылы табылады.","trap":"Өнімділікті табу үшін өнім массасын ауданға көбейтеміз.","problems":[{"q":"12 га жерден 36 т өнім жиналды. Гектарына неше тонна?","answer":"3","steps":["36 / 12 = 3 т/га.","жалпы өнімді ауданға бөл."]},{"q":"Гектарына 2,5 т өнім беретін 18 га жерден неше тонна жиналады?","answer":"45","steps":["2,5 × 18 = 45 т.","өнімділік тұрақты деп алынған."]}]},{"id":"practical-07","title":"Қаптама және материал шығыны","rule":"Қаптама есебінде керек материал, кесу шығыны және бүтін қап саны ескеріледі.","trap":"Қорап санын табуда кез келген бөлшек нәтижені төменге дөңгелектейміз.","problems":[{"q":"24 затты әр қорапқа 5-тен саламыз. Кемінде неше қорап керек?","answer":"5","steps":["24/5 = 4,8.","толық затты сыйдыру үшін жоғарыға дөңгелекте: 5."]},{"q":"40 м² еденге 10% артық қорымен плитка алынады. Неше м² сатып алу керек?","answer":"44","steps":["Қор 4 м².","40 + 4 = 44 м²."]}]},{"id":"practical-08","title":"Адам санының өзгеруі","rule":"Адам саны өзгергенде жаңа сан бастапқы санға келушілерді қосып, кетушілерді алу арқылы табылады.","trap":"25%-дық өсім кез келген топқа дәл 25 адам қосады.","problems":[{"q":"Автобуста 36 адам болды. 12 адам түсіп, 9 адам мінді. Қанша адам қалды?","answer":"33","steps":["36 − 12 + 9 = 33.","әрекет ретін сақта."]},{"q":"Үйірмеде 80 оқушы бар. Сан 25%-ға артты. Жаңа саны қанша?","answer":"100","steps":["Өсім 80 × 0,25 = 20.","80 + 20 = 100."]}]},{"id":"practical-09","title":"Тұрмыстық жағдайлар","rule":"Тұрмыстық есепте жауапты өмірлік мағынасына қарап тексеру қажет.","trap":"Толық бұйым санын табуда бөлшек нәтижені әрқашан жоғары дөңгелектейміз.","problems":[{"q":"18 жұмыртқа бір бәлішке 3-тен жұмсалады. Неше толық бәліш жасауға болады?","answer":"6","steps":["18 / 3 = 6.","жұмыртқа басқа мақсатқа жұмсалмайды."]},{"q":"25 м матадан бір бұйымға 4 м қажет. Неше толық бұйым тігіледі?","answer":"6","steps":["25 / 4 = 6,25.","толық бұйым саны 6, мата қалдығы 1 м."]}]},{"id":"practical-10","title":"Кесте, сызба және жарнама бойынша есептер","rule":"Жарнамадағы ұсыныстарды бірдей өлшемге не бірлік бағаға келтіріп салыстырамыз.","trap":"Қаптаманың жалпы бағасы төмен болса, бірлік бағасы міндетті түрде төмен.","problems":[{"q":"600 г өнім 1 200 ₸. Бір килограмының бағасы қанша теңге?","answer":"2000","steps":["600 г = 0,6 кг.","1 200 / 0,6 = 2 000 ₸/кг."]},{"q":"Акция: 3 дәптер бағасына 4 дәптер. Бір дәптер 300 ₸ болса, 4 дәптердің төлемі қанша?","answer":"900","steps":["Тек 3 дәптерге төлем бар.","3 × 300 = 900 ₸."]}]},{"id":"practical-11","title":"Бірнеше шартты біріктіретін күрделі есептер","rule":"Күрделі есепте шарттарды ретімен қолданып, аралық нәтижелерді сақтаймыз.","trap":"Бірнеше шартты есепте тек соңғы берілген санды пайдалану жеткілікті.","problems":[{"q":"20 оқушыға 1 500 ₸ билет, 10% топтық жеңілдік және барлығына 6 000 ₸ автобус төленді. Жалпы шығын қанша?","answer":"33000","steps":["Билет 30 000 × 0,9 = 27 000.","автобуспен 33 000 ₸."]},{"q":"300 км сапарға 100 км-ге 8 л, литрі 250 ₸, жол ақысы 1 500 ₸. Жалпы шығын қанша?","answer":"7500","steps":["Жанармай 24 л, құны 6 000 ₸.","жол ақысымен 7 500 ₸."]}]}],"number":15}];
const COURSE_LESSONS=CURRICULUM.flatMap(m=>m.lessons.map(l=>({...l,moduleId:m.id,moduleTitle:m.title,color:m.color,symbol:m.symbol})));
function courseLesson(id){return COURSE_LESSONS.find(l=>l.id===id);}
function numberAlternatives(value){const n=Number(value),delta=Math.abs(n)>=100?Math.max(5,Math.round(Math.abs(n)*.1)):Math.abs(n)<1?.1:Math.abs(n)<10?1:3;const options=[n,n+delta,n-delta,n+delta*2].map(v=>String(Math.round(v*1000000)/1000000).replace('.',','));return options;}
for(const m of CURRICULUM){
 const existing=TOPICS.find(t=>t.id===m.id),sample=m.lessons[0];
 const values={id:m.id,title:m.title,label:m.title,desc:sample.rule,symbol:m.symbol,color:m.color,zone:String(m.number).padStart(2,'0'),formula:sample.rule,lesson:[sample.rule,...sample.problems[0].steps,sample.trap+' — бұл қате түсінік.'].slice(0,4),example:sample.problems[0].q,steps:sample.problems[0].steps,alt:sample.problems[1].steps.join(' '),mistake:sample.trap+' — бұл қате түсінік.'};
 while(values.lesson.length<4)values.lesson.push(sample.problems[1].steps.join(' '));
 if(existing)Object.assign(existing,values);else TOPICS.push(values);
 m.lessons.forEach((l,j)=>{
  l.problems.forEach((p,k)=>{const o=numberAlternatives(p.answer),id=`course-${l.id}-${k+1}`;BANK.push({id,topic:m.id,lessonId:l.id,q:p.q,o,a:0,e:p.steps.join(' '),steps:p.steps,difficulty:k===0?1:2,type:(j+k)%3===0?'choice':'number',solution:p.answer,unit:'',visual:null});});
  const truth=j%2===0,statement=truth?l.rule:l.trap;
  BANK.push({id:`course-${l.id}-reason`,topic:m.id,lessonId:l.id,q:'Пікірдің ақиқаттығын анықта: «'+statement+'»',o:['Ақиқат','Жалған','Дерек жеткіліксіз','Жауап жоқ'],a:truth?0:1,e:l.rule,steps:[truth?'Бұл пікір дұрыс.':'Бұл пікір қате.',l.rule],difficulty:2,type:'tf'});
 });
}
TOPICS.sort((a,b)=>CURRICULUM.findIndex(m=>m.id===a.id)-CURRICULUM.findIndex(m=>m.id===b.id));
